  '\\nWe are sorry, but the message was not sent due to a settings error. Please contact the admin for assistance.\\n' => '\\nNous sommes désolés, mais le message n\'a pas été envoyé en raison d\'une erreur de paramètres. Veuillez contacter l\'administrateur pour obtenir de l\'aide.\\n',
