  '\\nPlease add the shortcode_message shortcode to the email template.\\n' => '\\nVeuillez ajouter le shortcode shortcode_message au modèle d\'e-mail.\\n',
  '\\nYour Email Template cannot exceed 10,000 characters.\\n' => '\\nVotre modèle d\'e-mail ne peut pas dépasser 10 000 caractères.\\n',
  '\\nPlease use HTML tags to create your email template.\\n' => '\\nVeuillez utiliser des balises HTML pour créer votre modèle d\'e-mail.\\n',
  '\\nAdd this shortcode inside a tag to display the title of the email.\\n' => '\\nAjoutez ce shortcode dans une balise pour afficher le titre de l\'e-mail.\\n',
  '\\nAdd this shortcode inside an HTML tag to display the message content of an email.\\n' => '\\nAjoutez ce shortcode dans une balise HTML pour afficher le contenu du message d\'un e-mail.\\n',
  '\\nTo display the website name, add this shortcode inside an HTML tag.\\n' => '\\nPour afficher le nom du site Web, ajoutez ce shortcode dans une balise HTML.\\n',
  '\\nAdd this shortcode within an HTML tag to display the Website URL.\\n' => '\\nAjoutez ce shortcode dans une balise HTML pour afficher l\'URL du site Web.\\n',
  '\\nYou can display the Admin Email address of your WordPress site by adding this shortcode within an HTML tag.\\n' => '\\nVous pouvez afficher l\'adresse e-mail de l\'administrateur de votre site WordPress en ajoutant ce shortcode dans une balise HTML.\\n',
