  '\\nCreate a payment form to collect online payments.\\n' => '\\nCréez un formulaire de paiement pour collecter les paiements en ligne.\\n',
  '\\nSubmit\\n' => '\\nSoumettre\\n',
  '\\nPurchase Order\\n' => '\\nBon de commande\\n',
  '\\nIt is not possible to include reCAPTCHA on payment forms.\\n' => '\\nIl n\'est pas possible d\'inclure reCAPTCHA sur les formulaires de paiement.\\n',
  '\\nThis site can send emails\\n' => '\\nCe site peut envoyer des e-mails\\n',
  '\\nWeekly email health and form activity report\\n' => '\\nRapport hebdomadaire sur l\'état des e-mails et l\'activité des formulaires\\n',
  '\\nAdds your form activity totals – forms, views and submissions – to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.\\n' => '\\nAjoute le total de vos activités de formulaire (formulaires, vues et soumissions) à l\'e-mail hebdomadaire que votre site envoie à l\'administrateur principal. Ces totaux sont lus sur votre propre site et ne sont jamais envoyés à WhiteStudio.\\n',
  'Last check: %s' => 'Dernière vérification :%s',
  '\\nNo automated email check has run yet.\\n' => '\\nAucune vérification automatique des e-mails n\'a encore été exécutée.\\n',
  '\\nCollect email delivery statistics\\n' => '\\nCollecter des statistiques de livraison d\'e-mails\\n',
  '\\nCounts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.\\n' => '\\nCompte le nombre d\'e-mails envoyés ou ayant échoué, les affiche dans le widget du tableau de bord et ajoute la section d\'état de livraison des e-mails à l\'e-mail hebdomadaire. Une fois par semaine, votre site effectue un test de livraison et rapporte le résultat. Seuls les utilisateurs Pro peuvent désactiver cette fonctionnalité.\\n',
  'Actions' => 'Actions',
  '\\nInterval\\n' => '\\nIntervalle\\n',
  '[[\'Next Billing Date\\n' => '[[\'Date de facturation suivante\\n',
  'Daily' => 'Quotidiennement',
  'Monthly' => 'Mensuel',
  'Weekly' => 'Hebdomadaire',
  '\\nYearly\\n' => '\\nAnnuelle\\n',
  '\\nHow to activate the Pro version of Flux Forms\\n' => '\\nComment activer la version Pro de Flux Forms\\n',
  '\\nUploaded File\\n' => '\\nFichier téléchargé\\n',
  '\\nYour internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.\\n' => '\\nVotre connexion Internet a été perdue, mais ne vous inquiétez pas, nous avons enregistré les informations que vous avez saisies sur ce formulaire. Une fois que vous êtes reconnecté à Internet, vous pouvez facilement envoyer vos informations en cliquant sur le bouton Soumettre.\\n',
  '\\nPlease ensure that you have a stable internet connection and try again.\\n' => '\\nVeuillez vous assurer que vous disposez d\'une connexion Internet stable et réessayer.\\n',
  '\\nThere was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.\\n' => '\\nUn problème est survenu lors du téléchargement du fichier et le formulaire n\'a pas été soumis. Veuillez vérifier que votre connexion Internet est stable et réessayer.\\n',
  'Options' => 'Possibilités',
  '\\nYou are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)\\n' => '\\nVous rencontrez des problèmes avec jQuery. Veuillez contacter l\'administrateur pour obtenir de l\'aide. (Code d\'erreur : JQ-500)\\n',
  '\\nYour session has expired. Please refresh the page and try again.\\n' => '\\nVotre session a expiré. Veuillez actualiser la page et réessayer.\\n',
  '\\nBasic\\n' => '\\nBasique\\n',
  'Blank' => 'Vide',
  '\\nSign-In|Up\\n' => '\\nConnexion|Se connecter\\n',
  '\\nAdvance\\n' => '\\nAvance\\n',
  'All' => 'Tout',
  '\\nThank you Page\\n' => '\\nMerci Page\\n',
  '\\nRedirect page\\n' => '\\nPage de redirection\\n',
  '\\nPlease wait, you will be redirected shortly.\\n' => '\\nVeuillez patienter, vous serez redirigé sous peu.\\n',
  '\\nPersia payment\\n' => '\\nPaiement Perse\\n',
  '[[\'Unlock Pro Features Today\\n' => '[[\'Débloquez les fonctionnalités Pro aujourd\'hui\\n',
  '\\nUpgrade to Pro for just%1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s\\n' => '\\n Passez à Pro pour seulement%1$s%2$s%3$s/ an et accédez à des fonctionnalités puissantes, notamment des champs de formulaire avancés, des intégrations de paiement, une logique conditionnelle, des formulaires en plusieurs étapes, des téléchargements de fichiers, la sécurité et la protection anti-spam et une assistance prioritaire.%4$sAfficher les fonctionnalités Pro%5$s\\n',
  '\\nAdd-on\\n' => '\\nModule complémentaire\\n',
  '\\nAdd-ons\\n' => '\\nModules complémentaires\\n',
  '[[\'Stripe Payment Add-on\\n' => '[[\'Module complémentaire de paiement Stripe\\n',
  '\\nThe Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.\\n' => '\\nLe module complémentaire Stripe pour Flux Forms vous permet d\'intégrer votre site WordPress à Stripe pour le traitement des paiements, les dons et les commandes en ligne.\\n',
  '[[\'Offline Forms Add-on\\n' => '[[\'Module complémentaire Formulaires hors ligne\\n',
  '\\nThe Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.\\n' => '\\nLe module complémentaire Offline Forms pour Flux Forms permet aux utilisateurs d\'enregistrer leur progression lorsqu\'ils remplissent des formulaires dans des situations hors ligne.\\n',
  'Install' => 'Installer',
  '[["Please update Flux Forms before trying again.\\n' => '[["Veuillez mettre à jour Flux Forms avant de réessayer.\\n',
  '\\nActivation of offline form mode.\\n' => '\\nActivation du mode formulaire hors ligne.\\n',
  '\\nBefore activating this option, install\\n' => '\\nAvant d\'activer cette option, installez\\n',
  '\\nTo create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.\\n' => '\\nPour créer un formulaire de paiement permettant de collecter des paiements en ligne, vous devez d\'abord installer un module complémentaire de paiement tel que le module complémentaire Stripe.\\n',
  '\\nAll formats\\n' => '\\nTous les formats\\n',
  '\\nEFB SMS Add-on\\n' => '\\nModule complémentaire SMS EFB\\n',
  '\\nEnable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.\\n' => '\\nActivez la fonctionnalité SMS dans vos formulaires avec le module complémentaire EFB SMS, vous permettant de valider des numéros de mobile et d\'envoyer des codes de confirmation par SMS, ainsi que de recevoir des notifications via le service SMS.\\n',
  '\\nAdvanced confirmation code Add-on\\n' => '\\nModule complémentaire de code de confirmation avancé\\n',
  '\\nSend a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.\\n' => '\\nEnvoyez un code de confirmation par e-mail ou SMS aux utilisateurs et/ou administrateurs, leur permettant d\'accéder rapidement aux nouvelles réponses.\\n',
  '\\nBox Checklist\\n' => '\\nListe de contrôle des cases\\n',
  '\\nRadio Checklist\\n' => '\\nListe de contrôle radio\\n',
  'Qty' => 'Quantité',
  '\\nThis is a warning for WPBakery users. For more information, please click here.\\n' => '\\nCeci est un avertissement pour les utilisateurs de WPBakery. Pour plus d\'informations, veuillez cliquer ici.\\n',
  '\\nAre you sure you want to close replies to this message?\\n' => '\\nÊtes-vous sûr de vouloir fermer les réponses à ce message ?\\n',
  '\\nAre you sure you want to open the responses to this message?\\n' => '\\nÊtes-vous sûr de vouloir ouvrir les réponses à ce message ?\\n',
  '\\nThe response has been closed by Admin.\\n' => '\\nLa réponse a été fermée par l\'administrateur.\\n',
  '\\nThe response has been opened by Admin.\\n' => '\\nLa réponse a été ouverte par l\'administrateur.\\n',
  'Open' => 'Ouvert',
  '\\n$NN/year\\n' => '\\n$NN/an\\n',
  '\\ncolumns\\n' => '\\ncolonnes\\n',
  '\\ncolumn\\n' => '\\ncolonne\\n',
  '\\nI would like to localize Flux Forms.\\n' => '\\nJe souhaite localiser Flux Forms.\\n',
  '\\nMax length\\n' => '\\nLongueur maximale\\n',
  '\\nMin length\\n' => '\\nLongueur minimale\\n',
  '\\nThe maximum number of characters allowed in the input element is 524288\\n' => '\\nLe nombre maximum de caractères autorisés dans l\'élément d\'entrée est de 524 288\\n',
  '\\nPlease enter a value that is at least NN characters long.\\n' => '\\nVeuillez saisir une valeur comportant au moins NN caractères.\\n',
  '\\nPlease enter a number that is greater than or equal to NN.\\n' => '\\nVeuillez saisir un nombre supérieur ou égal à NN.\\n',
  '\\nPlease Enter a maximum of NN Characters For this field\\n' => '\\nVeuillez saisir un maximum de NN caractères pour ce champ\\n',
  '\\nPlease enter a number that is less than or equal to NN\\n' => '\\nVeuillez saisir un nombre inférieur ou égal à NN\\n',
  '\\nMax\\n' => '\\nMaximum\\n',
  '\\nMin\\n' => '\\nMin\\n',
  '\\nMinimum entry must be lower than the maximum entry\\n' => '\\nL\'entrée minimale doit être inférieure à l\'entrée maximale\\n',
  'Disabled' => 'Désactivé',
  '\\nHide the label\\n' => '\\nMasquer l\'étiquette\\n',
  '\\nHide label on mobile\\n' => '\\nMasquer l\'étiquette sur mobile\\n',
  '\\nHide description on mobile\\n' => '\\nMasquer la description sur mobile\\n',
  '\\nHide all labels on mobile\\n' => '\\nMasquer toutes les étiquettes sur mobile\\n',
  '\\nClick here for more details\\n' => '\\nCliquez ici pour plus de détails\\n',
  '\\nLabel of the ON status\\n' => '\\nÉtiquette de l\'état ON\\n',
  '\\nLabel of the OFF status\\n' => '\\nÉtiquette de l\'état OFF\\n',
  '\\n5 Point Scale\\n' => '\\nÉchelle de 5 points\\n',
  '\\nNet Promoter Score\\n' => '\\nNet Promoter Score\\n',
  '\\nNPS Table Matrix\\n' => '\\nMatrice de table NPS\\n',
  '\\nJalali Date\\n' => '\\nDate Jalali\\n',
  '\\nHijri Date\\n' => '\\nDate de l\'Hégire\\n',
  '\\nInstall the add-on\\n' => '\\nInstaller le module complémentaire\\n',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Jalili date addons\\n' => '\\nVeuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Jalili\\n',
  '\\nPlease go to the Add-ons Page of Flux Forms plugin and install the Hijri date addons\\n' => '\\nVeuillez accéder à la page des modules complémentaires du plugin Flux Forms et installer les modules complémentaires de date Hijri\\n',
  'warning' => 'avertissement',
  '\\ndate & time\\n' => '\\ndate et heure\\n',
  '\\nEnable file upload in the response box\\n' => '\\nActiver le téléchargement de fichiers dans la zone de réponse\\n',
  '\\nEnable Google reCAPTCHA in the response box\\n' => '\\nActivez Google reCAPTCHA dans la zone de réponse\\n',
  '\\nEnable download button in the response box\\n' => '\\nActiver le bouton de téléchargement dans la zone de réponse\\n',
  '\\nDisplay the IP addresses of users in the response box.\\n' => '\\nAffichez les adresses IP des utilisateurs dans la zone de réponse.\\n',
  '\\nPersia Payment Add-on\\n' => '\\nModule complémentaire de paiement Persia\\n',
  '\\nThe Persia payment add-on for Flux Forms enables you to connect your website with Persia payment to process payments, donations, and online orders.\\n' => '\\nLe module complémentaire de paiement Persia pour Flux Forms vous permet de connecter votre site Web à Persia Payment pour traiter les paiements, les dons et les commandes en ligne.\\n',
  '\\nJalali Date Add-on\\n' => '\\nModule complémentaire de date Jalali\\n',
  '\\nThe Jalali Date add-on allows you to add a Jalali date field to your forms and create any type of form that includes this Shamsi date field.\\n' => '\\nLe module complémentaire Jalali Date vous permet d\'ajouter un champ de date Jalali à vos formulaires et de créer tout type de formulaire incluant ce champ de date Shamsi.\\n',
  '\\nHijri Date Add-on\\n' => '\\nModule complémentaire Date Hijri\\n',
  '\\nThe Hijri Date add-on allows you to add a Hijri date field to your forms and create any type of form that includes this field.\\n' => '\\nLe module complémentaire Hijri Date vous permet d\'ajouter un champ de date Hijri à vos formulaires et de créer tout type de formulaire incluant ce champ.\\n',
  '\\nSMS service Add-on\\n' => '\\nModule complémentaire de service SMS\\n',
  '\\nThe SMS service add-on enables you to receive notification SMS messages when you or your customers receive new messages or responses.\\n' => '\\nLe module complémentaire du service SMS vous permet de recevoir des messages SMS de notification lorsque vous ou vos clients recevez de nouveaux messages ou réponses.\\n',
  '\\nPlease install either the Hijri or Jalali date add-on. You cannot install both add-ons simultaneously.\\n' => '\\nVeuillez installer le module complémentaire de date Hijri ou Jalali. Vous ne pouvez pas installer les deux modules complémentaires simultanément.\\n',
  '\\nResponse box\\n' => '\\nBoîte de réponse\\n',
  '\\nRegions Drop-Down\\n' => '\\nliste déroulante des régions\\n',
  '\\nYou are seeing this message because your required add-ons are being installed. Please wait a few minutes and then visit this page again. If it has been more than five minutes and nothing has happened, please contact the support team of Flux Forms at Whitestudio.team.\\n' => '\\nVous voyez ce message car les modules complémentaires requis sont en cours d\'installation. Veuillez patienter quelques minutes, puis visiter à nouveau cette page. Si plus de cinq minutes se sont écoulées et que rien ne s\'est produit, veuillez contacter l\'équipe d\'assistance de Flux Forms sur Whitestudio.team.\\n',
  '\\nThe cell phone number is incorrect\\n' => '\\nLe numéro de téléphone portable est incorrect\\n',
  '\\nInvalid country code\\n' => '\\nCode pays invalide\\n',
  '\\nThe cell phone number is too short\\n' => '\\nLe numéro de téléphone portable est trop court\\n',
  '\\nThe cell phone number is too long\\n' => '\\nLe numéro de téléphone portable est trop long\\n',
  '\\nPlease select the number of countries to display within an acceptable range.\\n' => '\\nVeuillez sélectionner le nombre de pays à afficher dans une plage acceptable.\\n',
  '\\nDisabled Field\\n' => '\\nChamp désactivé\\n',
  '\\nHidden Field\\n' => '\\nChamp caché\\n',
  '[[\'Select a country to display a list of states/provinces.\\n' => '[[\'Sélectionnez un pays pour afficher une liste d\'états/provinces.\\n',
  '\\nSelect a state/province to display a list of cities.\\n' => '\\nSélectionnez un état/une province pour afficher une liste de villes.\\n',
  '\\nSMS Service Add-on\\n' => '\\nModule complémentaire de service SMS\\n',
  '[["This field is currently unavailable. Please contact the site administrator.\\n' => '[["Ce champ est actuellement indisponible. Veuillez contacter l\'administrateur du site.\\n',
  '\\nWould you like to customize the form using the colors of the active template?\\n' => '\\nVoulez-vous personnaliser le formulaire en utilisant les couleurs du modèle actif ?\\n',
  '\\nFlux Forms has utilized the colors of the active template. Please choose a color for each option below to customize the form you are creating based on the colors of your template. By selecting a color for each option below, the color of all form fields associated with that feature will change accordingly.\', \'en\']]' => '\\nFlux Forms a utilisé les couleurs du modèle actif. Veuillez choisir une couleur pour chaque option ci-dessous afin de personnaliser le formulaire que vous créez en fonction des couleurs de votre modèle. En sélectionnant une couleur pour chaque option ci-dessous, la couleur de tous les champs de formulaire associés à cette fonctionnalité changera en conséquence.\', \'fr\']]',
  '\\nButtons text colors\\n' => '\\nCouleurs du texte des boutons\\n',
  '\\nattached files\\n' => '\\nfichiers joints\\n',
  '\\nDefault selected\\n' => '\\nSélectionné par défaut\\n',
  '\\nShow attributes\\n' => '\\nAfficher les attributs\\n',
  '\\nHide attributes\\n' => '\\nMasquer les attributs\\n',
  '\\nThe ID length should be at least 3 characters long.\\n' => '\\nLa longueur de l\'ID doit comporter au moins 3 caractères.\\n',
  '\\nThe ID value must be unique, as it is already being used in this field. Please try a new, unique value.\\n' => '\\nLa valeur de l\'ID doit être unique, car elle est déjà utilisée dans ce champ. Veuillez essayer une nouvelle valeur unique.\\n',
  '\\nImage picker\\n' => '\\nSélecteur d\'images\\n',
  '\\nInsert an image url\\n' => '\\nInsérer une URL d\'image\\n',
  '\\nNew Booking Form\\n' => '\\nNouveau formulaire de réservation\\n',
  '\\nConditional Logic Add-on\\n' => '\\nModule complémentaire de logique conditionnelle\\n',
  '\\nConditional logic Add-on\\n' => '\\nModule complémentaire de logique conditionnelle\\n',
  '\\nThe Conditional Logic Add-on enables dynamic and interactive forms based on specific user inputs or conditional rules. It allows for highly personalized forms tailored to meet users’ unique needs.\\n' => '\\nLe module complémentaire Conditional Logic permet d\'activer des formulaires dynamiques et interactifs basés sur des entrées utilisateur spécifiques ou des règles conditionnelles. Il permet de créer des formulaires hautement personnalisés adaptés pour répondre aux besoins uniques des utilisateurs.\\n',
  '\\nThe Conditional Logic module failed to load. Please refresh the page; if the problem continues, deactivate and reactivate the Conditional Logic add-on.\\n' => '\\nLe module de logique conditionnelle n\'a pas pu être chargé. Veuillez actualiser la page ; si le problème persiste, désactivez et réactivez le module complémentaire Conditional Logic.\\n',
  '\\nStop after this rule matches\\n' => '\\nArrêtez après que cette règle corresponde\\n',
  '\\nIF\\n' => '\\nSI\\n',
  '\\nTHEN\\n' => '\\nALORS\\n',
  '\\nTest Mode\\n' => '\\nMode Test\\n',
  '\\nRun Test\\n' => '\\nExécuter le test\\n',
  '\\nMatched\\n' => '\\nCorrespondance\\n',
  '\\nNot matched\\n' => '\\nNe correspond pas\\n',
  'Skipped' => 'Sauté',
  '\\nNo fields found.\\n' => '\\nAucun champ trouvé.\\n',
  '\\nYou can create up to%1$s%2$son your current plan. Upgrade to Pro for unlimited access.\\n' => '\\nVous pouvez créer jusqu\'à%1$s%2$ssur votre forfait actuel. Passez à Pro pour un accès illimité.\\n',
  '\\nInspector\\n' => '\\nInspecteur\\n',
  '\\nRule trace\\n' => '\\nTrace de règle\\n',
  '\\nFinal values\\n' => '\\nValeurs finales\\n',
  '\\nEffects\\n' => '\\nEffets\\n',
