  '\\nTo enable SMS notifications in your forms, choose a delivery method.\\n' => '\\nPour activer les notifications par SMS dans vos formulaires, choisissez un mode de livraison.\\n',
  '\\nSelect an SMS delivery method\\n' => '\\nSélectionnez un mode de livraison par SMS\\n',
  '\\nEnter administrators’ mobile numbers\\n' => '\\nEntrez les numéros de mobile des administrateurs\\n',
  '\\nFlux Forms SMS service\\n' => '\\nService SMS Flux Forms\\n',
  '\\nFormat: +12345678900 or +1 (234) 567-8900\\n' => '\\nFormat : +12345678900 ou +1 (234) 567-8900\\n',
  '\\nWSMS plugin by VeronaLabs\\n' => '\\nPlugin WSMS de VeronaLabs\\n',
  '\\nWSMS plugin by VeronaLabs is not installed or activated. Please select another option, or install and configure WSMS.\\n' => '\\nLe plug-in WSMS de VeronaLabs n\'est ni installé ni activé. Veuillez sélectionner une autre option ou installer et configurer WSMS.\\n',
  '\\nTo use this option, please install the NN add-ons from the Flux Forms plugin\\\'s add-ons page.\\n' => '\\nPour utiliser cette option, veuillez installer les modules complémentaires NN à partir de la page des modules complémentaires du plugin Flux Forms.\\n',
  '\\nSMS Notifications\\n' => '\\nNotifications SMS\\n',
  '\\nEnter the administrators’ mobile numbers to receive SMS notifications, such as alerts or new messages.\\n' => '\\nSaisissez les numéros de mobile des administrateurs pour recevoir des notifications SMS, telles que des alertes ou de nouveaux messages.\\n',
  '[[\'All SMS notifications sent by Flux Forms will be delivered to the numbers entered here.\\n' => '[[\'Toutes les notifications SMS envoyées par Flux Forms seront envoyées aux numéros saisis ici.\\n',
  '\\nChoose Email notification content\\n' => '\\nChoisissez le contenu de la notification par e-mail\\n',
  '\\nSend email with confirmation code and link\\n' => '\\nEnvoyer un e-mail avec le code de confirmation et le lien\\n',
  '\\nSend email with submitted form content and link\', \'en\']]' => '\\nEnvoyer un e-mail avec le contenu du formulaire soumis et le lien\', \'fr\']]',
  '\\nTo view the map and selected points, simply click here to navigate to the received message page\\n' => '\\nPour afficher la carte et les points sélectionnés, cliquez simplement ici pour accéder à la page des messages reçus\\n',
  'SMS' => 'SMS',
  'Documentation' => 'Documentation',
  '\\nClick on the Settings button on the panel page of Flux Forms Plugin and configure the SMS sending method. Then, try again.\\n' => '\\nCliquez sur le bouton Paramètres sur la page du panneau du plugin Flux Forms et configurez la méthode d\'envoi de SMS. Ensuite, réessayez.\\n',
