  '\\nThis is a sample form submission.\\n' => '\\nCeci est un exemple de soumission de formulaire.\\n',
  '\\nMy Website\\n' => '\\nMon site Web\\n',
  'Bold' => 'Audacieux',
  'Italic' => 'Italique',
  'Underline' => 'Souligner',
  'Clear formatting' => 'Formatage clair',
  '\\nToggle navigation\\n' => '\\nBasculer la navigation\\n',
  '\\nView toggle\\n' => '\\nAffichage bascule\\n',
  '\\nLocate Me\\n' => '\\nLocalisez-moi\\n',
  '\\nError fetching address\\n' => '\\nErreur lors de la récupération de l\'adresse\\n',
  '\\nGeolocation is not supported by this browser.\\n' => '\\nLa géolocalisation n\'est pas prise en charge par ce navigateur.\\n',
  '\\nverify\\n' => '\\nvérifier\\n',
  'Failed' => 'Échec',
  '\\nThe form cannot be submitted because it requires a payment method, which is currently missing. If you are the Admin, please add a payment method to the form or change the form type to "Form" or "Survey".\\n' => '\\nLe formulaire ne peut pas être soumis car il nécessite un mode de paiement, qui est actuellement manquant. Si vous êtes l\'administrateur, veuillez ajouter un mode de paiement au formulaire ou modifier le type de formulaire en "Formulaire" ou "Enquête".\\n',
  'Payments' => 'Paiements',
  '\\nCache Plugin Detected\\n' => '\\nPlug-in de cache détecté\\n',
  '\\nThe following cache plugins may interfere with form functionality. If you experience issues, please review the documentation.\\n' => '\\nLes plugins de cache suivants peuvent interférer avec la fonctionnalité du formulaire. Si vous rencontrez des problèmes, veuillez consulter la documentation.\\n',
  'Plugin' => 'Plugin',
  'Version' => 'Version',
  '\\nRead more about cache compatibility\\n' => '\\nEn savoir plus sur la compatibilité du cache\\n',
  'Dismiss' => 'Rejeter',
  '\\nDismiss All\\n' => '\\nTout ignorer\\n',
  '\\nDismiss%s\\n' => '\\nIgnorer%s\\n',
  '\\nSecurity Plugin Detected\\n' => '\\nPlug-in de sécurité détecté\\n',
  '\\nThe following security plugin may block form submissions with 403 errors. It may block the REST API, remove the X-WP-Nonce header, or apply firewall rules to form requests.\\n' => '\\nLe plugin de sécurité suivant peut bloquer les soumissions de formulaires contenant des erreurs 403. Il peut bloquer l\'API REST, supprimer l\'en-tête X-WP-Nonce ou appliquer des règles de pare-feu aux requêtes de formulaire.\\n',
  '\\nRead more about security plugin compatibility\\n' => '\\nEn savoir plus sur la compatibilité des plugins de sécurité\\n',
  '\\nAuto-Populate Add-on\\n' => '\\nModule complémentaire de remplissage automatique\\n',
  '\\nThe Auto-Populate add-on enables you to automatically populate form fields from datasets, previously submitted forms, or external APIs.\\n' => '\\nLe module complémentaire Auto-Populate vous permet de remplir automatiquement les champs de formulaire à partir d\'ensembles de données, de formulaires précédemment soumis ou d\'API externes.\\n',
  '\\nForm Security & Spam Protection\\n' => '\\nSécurité des formulaires et protection anti-spam\\n',
  '\\nBehavior-based anti-spam and API abuse protection with rate limits and a stop-loss for paid notifications such as SMS, Telegram, email and webhooks.\\n' => '\\nProtection anti-spam et anti-abus d\'API basée sur le comportement avec des limites de débit et un stop-loss pour les notifications payantes telles que les SMS, les télégrammes, les e-mails et les webhooks.\\n',
  '\\nGoogle Sheet Add-on\\n' => '\\nModule complémentaire Google Sheet\\n',
  '\\nAutomatically send form submissions to your Google Sheets in real time. Connect a service account, map fields to columns, and keep a live, styled spreadsheet of every response — no webhook or browser login required.\\n' => '\\nEnvoyez automatiquement les soumissions de formulaires à vos feuilles de calcul Google en temps réel. Connectez un compte de service, mappez les champs aux colonnes et conservez une feuille de calcul stylisée et dynamique de chaque réponse : aucun webhook ou connexion au navigateur n\'est requis.\\n',
  '\\nPlease fill in all required fields\\n' => '\\nVeuillez remplir tous les champs obligatoires\\n',
  '\\nEmail Server Status\\n' => '\\nÉtat du serveur de messagerie\\n',
  '\\nThe test email never arrived\\n' => '\\nL\'e-mail de test n\'est jamais arrivé\\n',
  '\\nYour WordPress site cannot send emails reliably. This is a very common hosting issue — the default PHP mail function is often blocked or ends up in spam. Installing an SMTP plugin routes your emails through a verified mail service and fixes this in minutes.\\n' => '\\nVotre site WordPress ne peut pas envoyer d\'e-mails de manière fiable. Il s\'agit d\'un problème d\'hébergement très courant : la fonction de messagerie PHP par défaut est souvent bloquée ou finit dans le spam. L\'installation d\'un plug-in SMTP achemine vos e-mails via un service de messagerie vérifié et résout ce problème en quelques minutes.\\n',
  '\\nWordPress sent the email - it just never arrived\\n' => '\\nWordPress a envoyé l\'e-mail - il n\'est tout simplement jamais arrivé\\n',
  '\\nYour site handed the message to your mail server successfully, so WordPress and this plugin did their part. It was lost, delayed or rejected afterwards - most often the receiving mailbox filed it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.\\n' => '\\nVotre site a transmis le message à votre serveur de messagerie avec succès, donc WordPress et ce plugin ont fait leur part. Il a été perdu, retardé ou rejeté par la suite - le plus souvent, la boîte aux lettres de réception l\'a classé comme spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante. L\'envoi via un service SMTP, avec des enregistrements SPF et DKIM pour votre domaine, est ce qui résout ce problème.\\n',
  '\\nWordPress could not send the email\\n' => '\\nWordPress n\'a pas pu envoyer l\'e-mail\\n',
  '\\nThe message never left your website: WordPress returned an error while sending it. Install and configure an SMTP plugin, or ask your host whether PHP mail is disabled.\\n' => '\\nLe message n\'a jamais quitté votre site Web : WordPress a renvoyé une erreur lors de son envoi. Installez et configurez un plugin SMTP, ou demandez à votre hébergeur si la messagerie PHP est désactivée.\\n',
  '\\nYour emails arrive, but will most likely land in spam\\n' => '\\nVos e-mails arrivent, mais atterriront très probablement dans les spams\\n',
  '[[\'Delivery itself works - the test message reached us. What is missing is trust: sending through an SMTP service and adding SPF and DKIM records for your domain is what moves your emails from the spam folder to the inbox.\\n' => '[[\'La livraison elle-même fonctionne - le message de test nous est parvenu. Ce qui manque, c\'est la confiance : l\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine sont ce qui déplace vos e-mails du dossier spam vers la boîte de réception.\\n',
  '\\nThe test email was delivered with a deliverability score of%1$sout of 100. Under%2$s, most mailboxes file messages in the spam folder, so the people filling in your forms may never see them.\\n' => '\\nL\'e-mail de test a été envoyé avec un score de délivrabilité de%1$ssur 100. Sous%2$s, la plupart des boîtes aux lettres classent les messages dans le dossier spam, de sorte que les personnes qui remplissent vos formulaires risquent de ne jamais les voir.\\n',
  '\\nStep-by-step SMTP setup guide\\n' => '\\nGuide de configuration SMTP étape par étape\\n',
  '\\nYour email server is working. A detailed HTML report has been sent to%s.\\n' => '\\nVotre serveur de messagerie fonctionne. Un rapport HTML détaillé a été envoyé à%s.\\n',
  '\\nyour admin email address\\n' => '\\nvotre adresse e-mail d\'administrateur\\n',
  '\\nSpam Score Report on the Way!\\n' => '\\nRapport sur le score de spam en route !\\n',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent to%swithin the next few minutes.\\n' => '\\nUn rapport complet sur l\'état des e-mails (incluant votre score de spam, les détails de délivrabilité et les recommandations) sera envoyé à%sdans les prochaines minutes.\\n',
  '\\nEmail notifications may not be delivered\\n' => '\\nLes notifications par e-mail peuvent ne pas être envoyées\\n',
  '\\nThis form\'s email notification feature is enabled, but email delivery has not been verified and the latest spam score is%s/100. The form was saved, but admin notification emails may not reach you until SMTP/email delivery is fixed.\\n' => '\\nLa fonctionnalité de notification par e-mail de ce formulaire est activée, mais la livraison des e-mails n\'a pas été vérifiée et le dernier score de spam est%s/100. Le formulaire a été enregistré, mais les e-mails de notification de l\'administrateur risquent de ne pas vous parvenir tant que la livraison SMTP/e-mail n\'est pas corrigée.\\n',
  '\\nNotification emails are turned off\\n' => '\\nLes e-mails de notification sont désactivés\\n',
  '\\nFlux Forms will not send any email — neither to you nor to the person who submits this form — until "This site can send emails" is enabled in Email Settings.\\n' => '\\nFlux Forms n\'enverra aucun e-mail — ni à vous ni à la personne qui soumet ce formulaire — jusqu\'à ce que « Ce site peut envoyer des e-mails » soit activé dans les paramètres de messagerie.\\n',
  '[[\'Enable email sending\\n' => '[[\'Activer l\'envoi d\'e-mails\\n',
  '\\nClick "Check Email Server" to test delivery, turn this switch on, then press Save.\\n' => '\\nCliquez sur "Vérifier le serveur de messagerie" pour tester la livraison, activez ce commutateur, puis appuyez sur Enregistrer.\\n',
  '\\nDelivery is taking longer than expected\', \'en\']]' => '\\nLa livraison prend plus de temps que prévu\', \'fr\']]',
  '\\nWordPress sent the test email, but our server has not received it yet. This may be a temporary delay. Check the diagnostics below to troubleshoot.\\n' => '\\nWordPress a envoyé l\'e-mail de test, mais notre serveur ne l\'a pas encore reçu. Il peut s\'agir d\'un retard temporaire. Vérifiez les diagnostics ci-dessous pour résoudre les problèmes.\\n',
  '\\nPrepare Test\\n' => '\\nPréparer le test\\n',
  '\\nConnecting to WhiteStudio to generate a unique test email address.\\n' => '\\nConnexion à WhiteStudio pour générer une adresse e-mail de test unique.\\n',
  '\\nWordPress Sends the Email\\n' => '\\nWordPress envoie l\'e-mail\\n',
  '\\nWordPress hands a real message to your mail server. A tick here means WordPress sent it, not yet that it arrived.\\n' => '\\nWordPress transmet un vrai message à votre serveur de messagerie. Une coche ici signifie que WordPress l\'a envoyé, mais qu\'il n\'est pas encore arrivé.\\n',
  '\\nWaiting for Delivery\\n' => '\\nEn attente de livraison\\n',
  '\\nChecking whether the test email arrived at our server (usually takes a few seconds).\\n' => '\\nVérifier si l\'e-mail de test est arrivé sur notre serveur (cela prend généralement quelques secondes).\\n',
  '\\nQuick Result\\n' => '\\nRésultat rapide\\n',
  '\\nShowing the first delivery result — you will see right away if email is working.\\n' => '\\nAffichage du premier résultat de livraison : vous verrez immédiatement si le courrier électronique fonctionne.\\n',
  '\\nFull Report\\n' => '\\nRapport complet\\n',
  '\\nA detailed HTML report with full diagnostics is being prepared and emailed to you.\\n' => '\\nUn rapport HTML détaillé avec des diagnostics complets est en cours de préparation et vous est envoyé par courrier électronique.\\n',
  'Running' => 'Courir',
  'Finished' => 'Terminé',
  '\\nNeeds attention\\n' => '\\nBesoin d\'attention\\n',
  '\\n%sof 5 steps done\\n' => '\\n %s étapes sur 5 effectuées\\n',
  '\\nStep%sof 5\\n' => '\\nÉtape%ssur 5\\n',
  '\\n/ 100\\n' => '\\n/ 100\\n',
  '\\nTest started\\n' => '\\nTest démarré\\n',
  '[[\'A unique address is being generated for this test.\\n' => '[[\'Une adresse unique est générée pour ce test.\\n',
  '\\nWaiting for the email to arrive\\n' => '\\nEn attente de l\'arrivée de l\'e-mail\\n',
  '\\nWe check our server every few seconds. Please keep this page open.\\n' => '\\nNous vérifions notre serveur toutes les quelques secondes. Veuillez garder cette page ouverte.\\n',
  '\\nYour email server is healthy\\n' => '\\nVotre serveur de messagerie est sain\\n',
  '\\nThe test email arrived, and the subject and unique-code checks both passed.\\n' => '\\nL\'e-mail de test est arrivé et les vérifications de l\'objet et du code unique ont toutes deux réussi.\\n',
  '\\nDelivered, but likely to be filtered as spam\\n' => '\\nLivré, mais susceptible d\'être filtré comme spam\\n',
  '\\nDelivered, but deliverability is weak\\n' => '\\nLivré, mais la délivrabilité est faible\\n',
  '\\nNo email arrived\\n' => '\\nAucun e-mail n\'est arrivé\\n',
  '\\nNothing was received during the test window, so your server most likely cannot send email.\\n' => '\\nRien n\'a été reçu pendant la fenêtre de test, votre serveur ne pourra donc probablement pas envoyer d\'e-mails.\\n',
  '\\nThe test timed out\\n' => '\\nLe test a expiré\\n',
  '\\nThe test reached its time limit. Your server may be slow, or may block outbound email.\\n' => '\\nLe test a atteint sa limite de temps. Votre serveur peut être lent ou bloquer les e-mails sortants.\\n',
  '\\nThe test email could not be sent\\n' => '\\nL\'e-mail de test n\'a pas pu être envoyé\\n',
  '\\nWordPress returned an error while sending. See the message below.\\n' => '\\nWordPress a renvoyé une erreur lors de l\'envoi. Consultez le message ci-dessous.\\n',
  '\\nThe connection was lost\', \'en\']]' => '\\nLa connexion a été perdue\', \'fr\']]',
  '\\nNo answer came back from the server. Refresh the page and try again.\\n' => '\\nAucune réponse n\'est revenue du serveur. Actualisez la page et réessayez.\\n',
  '\\nThis test needs a higher plan\\n' => '\\nCe test nécessite un plan supérieur\\n',
  '\\nUpgrade your plan to run the full delivery test.\\n' => '\\nMettez à niveau votre plan pour exécuter le test de livraison complet.\\n',
  '\\nYour email server is working. A detailed HTML report has been sent to\\n' => '\\nVotre serveur de messagerie fonctionne. Un rapport HTML détaillé a été envoyé à\\n',
  '\\nA complete email health report — including your spam score, deliverability details, and recommendations — will be sent within the next few minutes to\\n' => '\\nUn rapport complet sur l\'état de santé des e-mails (incluant votre score de spam, les détails de délivrabilité et les recommandations) sera envoyé dans les prochaines minutes à\\n',
  '\\nUpgrade required\\n' => '\\nMise à niveau requise\\n',
