  '\\nThe missing add-on files could not be restored. Check the server connection and file permissions, then try again.\\n' => '\\nLes fichiers complémentaires manquants n\'ont pas pu être restaurés. Vérifiez la connexion au serveur et les autorisations de fichiers, puis réessayez.\\n',
  '\\nYou do not have permission to do this.\\n' => '\\nVous n\'êtes pas autorisé à faire cela.\\n',
  '\\nAll required add-ons were restored.\\n' => '\\nTous les modules complémentaires requis ont été restaurés.\\n',
  '\\nFinish updating Flux Forms\\n' => '\\nTerminer la mise à jour de Flux Forms\\n',
  '\\nSome add-on files are missing\\n' => '\\nCertains fichiers complémentaires sont manquants\\n',
  '\\nThe plugin was updated, so its add-ons must be reinstalled before this page can load. Click the button below to install them.\\n' => '\\nLe plugin a été mis à jour, ses modules complémentaires doivent donc être réinstallés avant que cette page puisse se charger. Cliquez sur le bouton ci-dessous pour les installer.\\n',
  '\\nOne or more add-on files are missing. Click the button below to reinstall them.\\n' => '\\nUn ou plusieurs fichiers complémentaires sont manquants. Cliquez sur le bouton ci-dessous pour les réinstaller.\\n',
  '\\nAutomatic recovery was attempted but did not finish. Review the reason below, fix it if necessary, then try again.\\n' => '\\nLa récupération automatique a été tentée mais n\'a pas abouti. Examinez la raison ci-dessous, corrigez-la si nécessaire, puis réessayez.\\n',
  '\\nRecover add-ons\\n' => '\\nRécupérer les modules complémentaires\\n',
  '\\nInstalling add-ons...\\n' => '\\nInstallation de modules complémentaires...\\n',
  '\\nInstallation complete.\\n' => '\\nInstallation terminée.\\n',
  '\\nClick to activate the add-ons.\\n' => '\\nCliquez pour activer les modules complémentaires.\\n',
  '[[\'Activate add-ons\\n' => '[[\'Activer les modules complémentaires\\n',
  '\\nInstallation failed. Please try again.\\n' => '\\nL\'installation a échoué. Veuillez réessayer.\\n',
  '\\nMissing add-ons:\', \'en\']]' => '\\nModules complémentaires manquants :\', \'fr\']]',
  '\\nWhy the recovery failed\\n' => '\\nPourquoi la récupération a échoué\\n',
  '\\nPreparing your form\\n' => '\\nPréparer votre formulaire\\n',
  '\\nAdd-ons restored successfully\\n' => '\\nModules complémentaires restaurés avec succès\\n',
  '\\nThe form is being prepared. This page will reload automatically.\\n' => '\\nLe formulaire est en cours de préparation. Cette page se rechargera automatiquement.\\n',
  '\\nThe page will reload automatically so the restored add-ons can be activated.\\n' => '\\nLa page se rechargera automatiquement afin que les modules complémentaires restaurés puissent être activés.\\n',
  '\\nReload now\\n' => '\\nRecharger maintenant\\n',
  '\\nThis form is temporarily unavailable.\\n' => '\\nCe formulaire est temporairement indisponible.\\n',
  '\\nWe could not restore a required form component automatically. Please try again shortly; the site administrator can view the exact recovery error in Flux Forms.\\n' => '\\nNous n\'avons pas pu restaurer automatiquement un composant de formulaire requis. Veuillez réessayer sous peu ; l\'administrateur du site peut afficher l\'erreur de récupération exacte dans Flux Forms.\\n',
  '\\nThe add-on is already installed.\\n' => '\\nLe module complémentaire est déjà installé.\\n',
  '\\nFile access status not checked yet. Please wait.\\n' => '\\nL\'état d\'accès au fichier n\'est pas encore vérifié. Veuillez patienter.\\n',
  '\\nError: server (%s) responded with an invalid request. responded code:%s\\n' => '\\nErreur : le serveur (%s) a répondu avec une requête non valide. code répondu :%s\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the%sserver\\n' => '\\nImpossible d\'installer les modules complémentaires de Flux Forms car le plugin ne parvient pas à se connecter au serveur%s\\n',
  '\\nYour Easy Form Builder Pro subscription has expired, so the Pro add-ons could not be downloaded. The plugin keeps working without them. Renew your subscription to restore all Pro features:\\n' => '\\nVotre abonnement Easy Form Builder Pro a expiré, les modules complémentaires Pro n\'ont donc pas pu être téléchargés. Le plugin continue de fonctionner sans eux. Renouvelez votre abonnement pour restaurer toutes les fonctionnalités Pro :\\n',
  '\\nThe version of the add-on is not compatible with the version of the Flux Forms plugin.\\n' => '\\nLa version du module complémentaire n\'est pas compatible avec la version du plugin Flux Forms.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to download files\\n' => '\\nImpossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas en mesure de télécharger des fichiers\\n',
  '\\nCannot install add-ons because this server has disabled the PHP filesystem functions needed to prepare the download. Please ask your hosting provider to enable mkdir and rename, or configure the WordPress filesystem.\\n' => '\\nImpossible d\'installer des modules complémentaires car ce serveur a désactivé les fonctions du système de fichiers PHP nécessaires à la préparation du téléchargement. Veuillez demander à votre fournisseur d\'hébergement d\'activer mkdir et de le renommer, ou de configurer le système de fichiers WordPress.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to move the downloaded file\\n' => '\\nImpossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas en mesure de déplacer le fichier téléchargé\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to unzip files\', \'en\']]' => '\\nImpossible d\'installer les modules complémentaires de Flux Forms car le plugin n\'est pas capable de décompresser les fichiers\', \'fr\']]',
  '\\nTo fix this, sign in to your%s, download the Add-ons Handler plugin from the Downloads section, then install and activate it. After that, activate the add-ons you need from the Add-ons Handler plugin.\\n' => '\\nPour résoudre ce problème, connectez-vous à votre%s, téléchargez le plug-in Add-ons Handler depuis la section Téléchargements, puis installez-le et activez-le. Après cela, activez les modules complémentaires dont vous avez besoin à partir du plug-in Add-ons Handler.\\n',
  '\\nWhiteStudio dashboard\\n' => '\\nTableau de bord WhiteStudio\\n',
  '\\nThis bundled add-on is missing from the plugin files.\\n' => '\\nCe module complémentaire fourni est absent des fichiers du plugin.\\n',
  '\\nThe add-on server returned an unexpected response.\\n' => '\\nLe serveur de module complémentaire a renvoyé une réponse inattendue.\\n',
  '\\nThe add-on could not be installed.\\n' => '\\nLe module complémentaire n\'a pas pu être installé.\\n',
  '\\nThe add-on server did not provide a download URL.\\n' => '\\nLe serveur du module complémentaire n\'a pas fourni d\'URL de téléchargement.\\n',
  '\\nThe add-on download URL is not an approved Flux Forms source.\\n' => '\\nL\'URL de téléchargement du module complémentaire n\'est pas une source Flux Forms approuvée.\\n',
  '\\nYour server could not reach%1$s, so the add-on could not be downloaded. This is almost always a firewall on your hosting blocking the outgoing request, not a problem with your licence. To install add-ons without any download at all, sign in at%2$sand download the Flux Forms Add-ons Handler plugin, then install it like any other plugin. It contains every add-on your licence covers.\\n' => '\\nVotre serveur n\'a pas pu atteindre%1$s, le module complémentaire n\'a donc pas pu être téléchargé. Il s\'agit presque toujours d\'un pare-feu sur votre hébergement bloquant la requête sortante, et non d\'un problème avec votre licence. Pour installer des modules complémentaires sans aucun téléchargement, connectez-vous sur%2$set téléchargez le plugin Flux Forms Add-ons Handler, puis installez-le comme n\'importe quel autre plugin. Il contient tous les modules complémentaires couverts par votre licence.\\n',
  '\\nIf you would rather fix the connection, ask your hosting provider why outgoing requests from%sare being blocked.\\n' => '\\nSi vous préférez réparer la connexion, demandez à votre fournisseur d\'hébergement pourquoi les requêtes sortantes de%ssont bloquées.\\n',
  '\\nFlux Forms: add-on downloads are being blocked\\n' => '\\nFlux Forms : les téléchargements de modules complémentaires sont bloqués\\n',
  '\\nAdd-on affected:%s\\n' => '\\nModule complémentaire concerné :%s\\n',
  '\\nNo response was recorded for this add-on.\\n' => '\\nAucune réponse n\'a été enregistrée pour ce module complémentaire.\\n',
  '\\nWritable\\n' => '\\nInscriptible\\n',
  '\\nNot writable — the add-on folder cannot be created or extracted into.\\n' => '\\nNon accessible en écriture : le dossier du module complémentaire ne peut pas être créé ou extrait.\\n',
  '\\nBlocked by WP_HTTP_BLOCK_EXTERNAL — outgoing requests are disabled on this site.\\n' => '\\nBloqué par WP_HTTP_BLOCK_EXTERNAL — les requêtes sortantes sont désactivées sur ce site.\\n',
  'Allowed' => 'Autorisé',
  '\\nDISABLE_WP_CRON is on — background retries only run if a server cron task calls wp-cron.php.\\n' => '\\nDISABLE_WP_CRON est activé : les tentatives en arrière-plan ne s\'exécutent que si une tâche périodique du serveur appelle wp-cron.php.\\n',
  'Site' => 'Site',
  '\\nPage that needed it\\n' => '\\nPage qui en avait besoin\\n',
  '\\nPlugin version\\n' => '\\nVersion du plugin\\n',
  'WordPress' => 'WordPress',
  '\\nAdd-on folder\\n' => '\\nDossier de modules complémentaires\\n',
  '\\nOutgoing requests\\n' => '\\nDemandes sortantes\\n',
  '\\nWP-Cron\\n' => '\\nWP-Cron\\n',
  '\\nAttempts made\\n' => '\\nTentatives effectuées\\n',
  '\\nFlux Forms could not reinstall its add-on files automatically. Forms that rely on those add-ons are showing a temporary message to visitors until this is resolved.\\n' => '\\nFlux Forms n\'a pas pu réinstaller automatiquement ses fichiers complémentaires. Les formulaires qui s\'appuient sur ces modules complémentaires affichent un message temporaire aux visiteurs jusqu\'à ce que le problème soit résolu.\\n',
  '\\nWhat is missing\\n' => '\\nCe qui manque\\n',
  '\\nDiagnostics\\n' => '\\nDiagnostics\\n',
  '\\nWhat to do next\\n' => '\\nQue faire ensuite\\n',
  '\\nOpen Flux Forms in your dashboard and use the Recover add-ons button.\\n' => '\\nOuvrez Flux Forms dans votre tableau de bord et utilisez le bouton Récupérer les modules complémentaires.\\n',
  '\\nIf the add-on folder is not writable, ask your host to allow writing to the plugin folder.\\n' => '\\nSi le dossier du module complémentaire n\'est pas accessible en écriture, demandez à votre hébergeur d\'autoriser l\'écriture dans le dossier du plugin.\\n',
  '\\nIf outgoing requests are blocked, ask your host to allow connections to the Flux Forms update server.\\n' => '\\nSi les requêtes sortantes sont bloquées, demandez à votre hébergeur d\'autoriser les connexions au serveur de mise à jour de Flux Forms.\\n',
  '\\nIf your Pro subscription has expired, renew it to restore the Pro add-ons.\\n' => '\\nSi votre abonnement Pro a expiré, renouvelez-le pour restaurer les modules complémentaires Pro.\\n',
  '\\nWe have made some updates. Please wait a few minutes before trying again.\\n' => '\\nNous avons effectué quelques mises à jour. Veuillez patienter quelques minutes avant de réessayer.\\n',
  '\\nCannot install add-ons of Flux Forms because the plugin is not able to connect to the whitestudio.team server\\n' => '\\nImpossible d\'installer les modules complémentaires de Flux Forms car le plugin ne parvient pas à se connecter au serveur whitestudio.team\\n',
  '\\nOne of the free features\\n' => '\\nUne des fonctionnalités gratuites\\n',
  '\\nImportant: Caching Plugin May Affect Flux Forms\\n' => '\\nImportant : Le plugin de mise en cache peut affecter les formulaires de flux\\n',
  '\\nThe following caching plugins are active on your site:\\n' => '\\nLes plugins de mise en cache suivants sont actifs sur votre site :\\n',
  '\\nPlugin Name\\n' => '\\nNom du plugin\\n',
  '\\nSlug\\n' => '\\nLimace\\n',
  '\\nPlease note that these plugins may affect the functionality of Flux Forms.\\n' => '\\nVeuillez noter que ces plugins peuvent affecter les fonctionnalités de Flux Forms.\\n',
  '\\nIf you experience any issues, please exclude the page where your form is published from caching or disable these plugins. For detailed guidance on how to set up this exclusion, please refer to the documentation of the respective caching plugin.\\n' => '\\nSi vous rencontrez des problèmes, veuillez exclure de la mise en cache la page sur laquelle votre formulaire est publié ou désactiver ces plugins. Pour obtenir des conseils détaillés sur la façon de configurer cette exclusion, veuillez vous référer à la documentation du plug-in de mise en cache concerné.\\n',
  '\\nSent by\\n' => '\\nEnvoyé par\\n',
  '\\nAction needed: Flux Forms Pro is paused on%s\\n' => '\\nAction nécessaire : Flux Forms Pro est en pause le%s\\n',
  '\\nFlux Forms could not confirm your Pro licence for%1$sdays in a row, so the Pro features on%2$sare paused for now.\\n' => '\\nFlux Forms n\'a pas pu confirmer votre licence Pro pendant%1$sjours consécutifs, les fonctionnalités Pro sur%2$ssont donc suspendues pour le moment.\\n',
  '\\nYour forms, entries and settings are untouched, every free feature keeps working, and your activation code is still stored — nothing was deleted.\\n' => '\\nVos formulaires, entrées et paramètres restent intacts, toutes les fonctionnalités gratuites continuent de fonctionner et votre code d\'activation est toujours stocké – rien n\'a été supprimé.\\n',
  '\\nOpen%1$sYT Form → Settings%2$sand press%1$sSave%2$s. That checks the licence again straight away; if the connection is back, Pro switches on within a minute.\\n' => '\\nOuvrez%1$sYT Form → Paramètres%2$set appuyez sur%1$sEnregistrer%2$s. Cela vérifie à nouveau la licence immédiatement ; si la connexion est rétablie, Pro s\'allume dans la minute.\\n',
  '\\nStill paused? Ask your hosting provider to allow outgoing HTTPS connections to%s— a firewall, proxy or regional block is the usual cause — then repeat step 1.\\n' => '\\nToujours en pause ? Demandez à votre fournisseur d\'hébergement d\'autoriser les connexions HTTPS sortantes vers%s(un pare-feu, un proxy ou un blocage régional est la cause habituelle), puis répétez l\'étape 1.\\n',
  '\\nIf your subscription has expired, or you moved this website to a new domain,%1$srenew or re-activate your licence%2$sand paste the new code into Settings.\', \'en\']]' => '\\nSi votre abonnement a expiré ou si vous avez déplacé ce site Web vers un nouveau domaine,%1$srenouvellez ou réactivez votre licence%2$set collez le nouveau code dans Paramètres.\', \'fr\']]',
  'Reason' => 'Raison',
  '\\nFirst failed check\\n' => '\\nPremier contrôle échoué\\n',
  '\\ngrace period\\n' => '\\ndélai de grâce\\n',
  '%s days' => '%sjours',
  '\\nActivation code\\n' => '\\nCode d\'activation\\n',
  '\\nError code\\n' => '\\nCode d\'erreur\\n',
  '\\nHow to bring Pro back\\n' => '\\nComment ramener Pro\\n',
  '\\nCheck my licence now\\n' => '\\nVérifiez ma licence maintenant\\n',
  '\\nStill stuck? Send the details above to%1$sour support team%2$sand we will take it from there.\\n' => '\\nToujours bloqué ? Envoyez les détails ci-dessus à%1$snotre équipe d\'assistance%2$set nous nous occuperons de là.\\n',
  '\\nThe licence server answered with an error and could not confirm your licence.\\n' => '\\nLe serveur de licences a répondu avec une erreur et n\'a pas pu confirmer votre licence.\\n',
  '\\nYour website could not reach the licence server — almost always a network, firewall or DNS restriction on the hosting side.\\n' => '\\nVotre site Web n\'a pas pu atteindre le serveur de licences – presque toujours à cause d\'une restriction réseau, pare-feu ou DNS du côté de l\'hébergement.\\n',
  '\\nThe licence server’s answer arrived damaged, usually because a security plugin, proxy or CDN changed it on the way.\\n' => '\\nLa réponse du serveur de licences est arrivée endommagée, généralement parce qu\'un plugin de sécurité, un proxy ou un CDN l\'a modifiée en cours de route.\\n',
  '\\nThe licence check could not be completed.\\n' => '\\nLa vérification de la licence n\'a pas pu être effectuée.\\n',
  '[[\'Your activation code has expired!\\n' => '[[\'Votre code d\'activation a expiré !\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue using the%sadd-on and all Pro features, please renew your subscription.\\n' => '\\nVotre abonnement Easy Form Builder Pro a expiré. Pour continuer à utiliser le module complémentaire%set toutes les fonctionnalités Pro, veuillez renouveler votre abonnement.\\n',
  '\\nRenew Subscription\\n' => '\\nRenouveler l\'abonnement\\n',
  '\\nPro Version Required\\n' => '\\nVersion Pro requise\\n',
  '\\nThe%sadd-on is a Pro feature. Please upgrade to Flux Forms Pro to access this functionality.\\n' => '\\nLe module complémentaire%sest une fonctionnalité Pro. Veuillez effectuer une mise à niveau vers Flux Forms Pro pour accéder à cette fonctionnalité.\\n',
  '\\nYour Easy Form Builder Pro subscription has expired. To continue enjoying all Pro features and keep your forms running,%1$sRenew your subscription now.%2$s\\n' => '\\nVotre abonnement Easy Form Builder Pro a expiré. Pour continuer à profiter de toutes les fonctionnalités Pro et maintenir vos formulaires opérationnels, %1$s Renouvelez votre abonnement maintenant. %2$s \\n',
  '\\nThe payment could not be verified yet.\\n' => '\\nLe paiement n\'a pas encore pu être vérifié.\\n',
  '\\nThis payment provider does not support refunds from the site.\\n' => '\\nCe fournisseur de paiement ne prend pas en charge les remboursements à partir du site.\\n',
  'Completed' => 'Terminé',
  'Active' => 'Actif',
  '\\nTrial\\n' => '\\nEssai\\n',
  'Pending' => 'En attente',
  'Processing' => 'Traitement',
  '\\nCanceled\\n' => '\\nAnnulé\\n',
  '\\nAmount mismatch\\n' => '\\nIncohérence de montant\\n',
  'Past due' => 'En souffrance',
  '\\nUnpaid\\n' => '\\nImpayé\\n',
  '\\nIncomplete\\n' => '\\nIncomplet\\n',
  '\\nExpired\\n' => '\\nExpiré\\n',
  'Refunded' => 'Remboursé',
  'Partly refunded' => 'Partiellement remboursé',
  '\\nSorry, you are not allowed to access this page.\\n' => '\\nDésolé, vous n\'êtes pas autorisé à accéder à cette page.\\n',
  '\\nPayments taken through your forms, from every payment provider. API keys and the active provider are set on the plugin Settings page, Payment tab.\\n' => '\\nPaiements effectués via vos formulaires, auprès de chaque fournisseur de paiement. Les clés API et le fournisseur actif sont définis sur la page Paramètres du plugin, onglet Paiement.\\n',
  'Settings saved.' => 'Paramètres enregistrés.',
  '\\nA Stripe webhook signing secret starts with "whsec_".\\n' => '\\nUn secret de signature de webhook Stripe commence par "whsec_".\\n',
  '\\nProviders and webhooks\\n' => '\\nFournisseurs et webhooks\\n',
  '\\nConfigured\\n' => '\\nConfiguré\\n',
  '\\nNot configured\', \'en\']]' => '\\nNon configuré\', \'fr\']]',
  '\\nWebhook URL for this provider (if it sends payment notifications):\\n' => '\\nURL du Webhook pour ce fournisseur (s\'il envoie des notifications de paiement) :\\n',
  '\\nRecent payments\\n' => '\\nPaiements récents\\n',
  '\\nNo payments yet.\\n' => '\\nAucun paiement pour l\'instant.\\n',
  '\\nConfirmation code\\n' => '\\nCode de confirmation\\n',
  'Provider' => 'Fournisseur',
  'Type' => 'Tapez',
  'Amount' => 'Montant',
  'Status' => 'Statut',
  '\\nTransaction ID\\n' => '\\nID de transaction\\n',
  '\\nSubscription\\n' => '\\nAbonnement\\n',
  '[[\'One-time\\n' => '[[\'Une seule fois\\n',
  '\\nThe latest%dpayments are shown.\\n' => '\\nLes derniers paiements%dsont affichés.\\n',
  '\\nTest provider (development only)\\n' => '\\nFournisseur de tests (développement uniquement)\\n',
  '[[\'Test outcome\\n' => '[[\'Résultat du test\\n',
  '\\nApprove every payment\\n' => '\\nApprouver chaque paiement\\n',
  '\\nDecline every payment\\n' => '\\nRefuser tout paiement\\n',
  '\\nNo money is taken. Development only.\\n' => '\\nAucun argent n\'est prélevé. Développement uniquement.\\n',
  '\\nTEST MODE: no card is charged.\\n' => '\\nMODE TEST : aucune carte n\'est débitée.\\n',
  '\\nTest provider: the payment was declined.\\n' => '\\nFournisseur de test : le paiement a été refusé.\\n',
  '[[\'Publishable key\\n' => '[[\'Clé publiable\\n',
  'Secret key' => 'Clé secrète',
  '\\nStripe is not configured on this site. Please contact the site administrator.\\n' => '\\nStripe n\'est pas configuré sur ce site. Veuillez contacter l\'administrateur du site.\\n',
  '\\nThe payment method of this form is not supported.\\n' => '\\nLe mode de paiement de ce formulaire n\'est pas pris en charge.\\n',
  '\\nThe payment could not be started. Please try again.\\n' => '\\nLe paiement n\'a pas pu démarrer. Veuillez réessayer.\\n',
  '\\nOptional but recommended: in the Stripe Dashboard add a webhook endpoint with this URL and the events payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated and customer.subscription.deleted, then paste its signing secret below.\\n' => '\\nFacultatif mais recommandé : dans le tableau de bord Stripe, ajoutez un point de terminaison webhook avec cette URL et les événements payment_intent.succeeded, payment_intent.payment_failed, payment_intent.canceled, charge.refunded, customer.subscription.updated et customer.subscription.deleted, puis collez son secret de signature ci-dessous.\\n',
  '\\nWebhook signing secret\\n' => '\\nSecret de signature du Webhook\\n',
  '\\nSaved - leave empty to keep it\\n' => '\\nEnregistré - laissez vide pour le conserver\\n',
  '\\nRemove the saved secret\\n' => '\\nSupprimer le secret enregistré\\n',
  '\\nInvalid or expired nonce\\n' => '\\nNonce non valide ou expiré\\n',
  '\\nNo payment provider is available on this site. Please contact the site administrator.\\n' => '\\nAucun prestataire de paiement n\'est disponible sur ce site. Veuillez contacter l\'administrateur du site.\\n',
  '\\nToo many payment attempts. Please wait a few minutes and try again.\\n' => '\\nTrop de tentatives de paiement. Veuillez patienter quelques minutes et réessayer.\\n',
  '\\nInvalid payment data. Please refresh the page and try again.\\n' => '\\nDonnées de paiement invalides. Veuillez actualiser la page et réessayer.\\n',
  '\\nThe payment provider is not configured on this site. Please contact the site administrator.\\n' => '\\nLe prestataire de paiement n\'est pas configuré sur ce site. Veuillez contacter l\'administrateur du site.\\n',
  '\\nNo payment amount detected. Please review your selected items and try again. If the problem persists, contact support.\\n' => '\\nAucun montant de paiement détecté. Veuillez vérifier les éléments sélectionnés et réessayer. Si le problème persiste, contactez l\'assistance.\\n',
  '\\nToo many requests. Please wait a moment and try again.\\n' => '\\nTrop de demandes. Veuillez patienter un moment et réessayer.\\n',
  '\\nPayment not found.\\n' => '\\nPaiement introuvable.\\n',
  '\\nYour payment has not been confirmed yet. Please wait a moment and try again. If the problem persists, contact the site administrator.\\n' => '\\nVotre paiement n\'a pas encore été confirmé. Veuillez patienter un moment et réessayer. Si le problème persiste, contactez l\'administrateur du site.\\n',
  '\\nOnline payment is not available at the moment. Please try again later or contact us.\\n' => '\\nLe paiement en ligne n\'est pas disponible pour le moment. Veuillez réessayer plus tard ou contactez-nous.\\n',
  '\\nActive payment provider\\n' => '\\nFournisseur de paiement actif\\n',
  '\\nPayment forms take card payments through this provider. Only installed providers are listed.\\n' => '\\nLes formulaires de paiement acceptent les paiements par carte via ce fournisseur. Seuls les fournisseurs installés sont répertoriés.\\n',
  '\\nSaved — leave empty to keep\\n' => '\\nEnregistré — laissez vide pour conserver\\n',
  '\\n%ssettings\\n' => '\\n Paramètres%s\\n',
  '\\nFlux Forms replaces%s, which has been deactivated. Your forms, entries and settings stay in place. You can delete the old plugin.\\n' => '\\nFlux Forms remplace%s, qui a été désactivé. Vos formulaires, entrées et paramètres restent en place. Vous pouvez supprimer l\'ancien plugin.\\n',
  '\\nUpdating amount...\\n' => '\\nMise à jour du montant...\\n',
  '\\nThe amount could not be verified. Please check your selections and try again.\\n' => '\\nLe montant n\'a pas pu être vérifié. Veuillez vérifier vos sélections et réessayer.\\n',
  '\\nSubject made by Flux Forms (with the tracking code)\\n' => '\\nSujet réalisé par Flux Forms (avec le code de suivi)\\n',
