  '\\nClear Logs\', \'en\']]' => '\\nEffacer les journaux\', \'fr\']]',
  '\\nThe Security & Spam Protection admin data could not be loaded. Another plugin may be blocking the script settings, or the page was cached. Reload the page; if it persists, disable admin script optimization for this page.\\n' => '\\nLes données administratives de sécurité et de protection anti-spam n\'ont pas pu être chargées. Un autre plugin bloque peut-être les paramètres du script ou la page a été mise en cache. Rechargez la page ; si le problème persiste, désactivez l\'optimisation du script d\'administration pour cette page.\\n',
  '\\nThe Security & Spam Protection panel failed to render. Reload the page or check the browser console.\\n' => '\\nLe panneau Sécurité et protection anti-spam n\'a pas pu s\'afficher. Actualisez la page ou consultez la console du navigateur.\\n',
  '\\nProtection is paused: required PHP functions are disabled on this server:%s. Ask your host to remove them from the disable_functions line in php.ini. Your forms keep working without protection until then.\\n' => '\\nLa protection est suspendue : les fonctions PHP requises sont désactivées sur ce serveur :%s. Demandez à votre hébergeur de les supprimer de la ligne Disable_functions dans php.ini. Vos formulaires continuent de fonctionner sans protection d\'ici là.\\n',
  '\\nProtection is paused: the add-on database tables could not be created. Check that the database user can CREATE tables, then reload this page.\\n' => '\\nLa protection est suspendue : les tables de la base de données complémentaire n\'ont pas pu être créées. Vérifiez que l\'utilisateur de la base de données peut CRÉER des tables, puis rechargez cette page.\\n',
  '\\nProtection is paused: the WordPress REST API is not available on this site.\\n' => '\\nLa protection est suspendue : l\'API REST WordPress n\'est pas disponible sur ce site.\\n',
