  '\\nReasons\\n' => '\\nRaisons\\n',
  '\\nSystem readiness\\n' => '\\nPréparation du système\\n',
  '\\nHuman Shield checks these functions before enforcing security rules.\\n' => '\\nHuman Shield vérifie ces fonctions avant d\'appliquer les règles de sécurité.\\n',
  '\\nPHP requirements are ready.\\n' => '\\nLes exigences PHP sont prêtes.\\n',
  '\\nSome required PHP functions are unavailable.", \'en\']]' => '\\nCertaines fonctions PHP requises ne sont pas disponibles.", \'fr\']]',
  '\\nREST API:\\n' => '\\nAPI REST :\\n',
  '\\navailable\\n' => '\\ndisponible\\n',
  '\\nmissing\\n' => '\\nmanquant\\n',
  '\\nTables:\\n' => '\\nTableaux :\\n',
  '\\nready\\n' => '\\nprêt\\n',
  '\\nnot ready yet\\n' => '\\npas encore prêt\\n',
  '\\nRecommended only after you verify PHP functions and tables are ready.\\n' => '\\nRecommandé uniquement après avoir vérifié que les fonctions et les tables PHP sont prêtes.\\n',
  '\\nTrust proxy IP headers\\n' => '\\nFaire confiance aux en-têtes IP du proxy\\n',
  '\\nUse forwarding headers only when the immediate peer matches the trusted proxy list below.\\n' => '\\nUtilisez les en-têtes de transfert uniquement lorsque le homologue immédiat correspond à la liste de proxys de confiance ci-dessous.\\n',
  '\\nTrusted proxy IPs\\n' => '\\nIP proxy de confiance\\n',
  '\\nOne exact IP or wildcard prefix per line. Add only your load balancer/CDN egress addresses; keep this empty when the origin is directly reachable.\\n' => '\\nUne adresse IP exacte ou un préfixe générique par ligne. Ajoutez uniquement vos adresses de sortie d\'équilibreur de charge/CDN ; gardez ce champ vide lorsque l\'origine est directement accessible.\\n',
  '\\nStore raw behavior metrics\\n' => '\\nStocker les métriques de comportement brutes\\n',
  '\\nKeep off for privacy unless debugging a rollout.\\n' => '\\nNe pas activer pour des raisons de confidentialité, sauf en cas de débogage d\'un déploiement.\\n',
  '\\nLog retention days\\n' => '\\nJournés de conservation des journaux\\n',
  '\\nHow long events should be retained.\\n' => '\\nCombien de temps les événements doivent être conservés.\\n',
  '\\nClient attestation timeout\\n' => '\\nDélai d\'expiration de l\'attestation client\\n',
  '\\nMilliseconds before the browser falls back to the normal request.\\n' => '\\nMillisecondes avant que le navigateur ne revienne à la requête normale.\\n',
  '\\nIf a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.\\n' => '\\nSi une fonction PHP requise est désactivée, activez-la dans php.ini Disable_functions ou demandez à l\'hôte de l\'autoriser. Les plugins de cache et de sécurité ne doivent pas mettre en cache ou réécrire les réponses POST de /wp-json/EmsfbShield/v1/*.\\n',
  '\\nSecurity & Spam Protection tabs\\n' => '\\nOnglets Sécurité et protection anti-spam\\n',
  '\\nSecurity log export is unavailable because this server has disabled a required PHP function:%s. Ask your hosting provider to enable it.\\n' => '\\nL\'exportation des journaux de sécurité n\'est pas disponible car ce serveur a désactivé une fonction PHP requise :%s. Demandez à votre fournisseur d\'hébergement de l\'activer.\\n',
  '\\nSecurity log export is unavailable because this server has disabled required PHP functions:%s. Ask your hosting provider to enable them.\\n' => '\\nL\'exportation des journaux de sécurité n\'est pas disponible car ce serveur a désactivé les fonctions PHP requises :%s. Demandez à votre fournisseur d\'hébergement de les activer.\\n',
  '\\nAuto-Populate Dataset\\n' => '\\nRemplir automatiquement l\'ensemble de données\\n',
  '\\nManage & Upload Datasets\\n' => '\\nGérer et télécharger des ensembles de données\\n',
