  '\\nSmart Cache\\n' => '\\nCache intelligent\\n',
  '\\nTotal Connections\\n' => '\\nTotal de connexions\\n',
  'Connections' => 'Connexions',
  '\\nAPI connections configured\\n' => '\\nConnexions API configurées\\n',
  '\\nHow to use API Integrations\\n' => '\\nComment utiliser les intégrations API\\n',
  '\\nFollow these steps to connect your external API\\n' => '\\nSuivez ces étapes pour connecter votre API externe\\n',
  '\\nClick "Add API Connection" to create a new connection and enter your API endpoint URL.\\n' => '\\nCliquez sur "Ajouter une connexion API" pour créer une nouvelle connexion et saisissez l\'URL de votre point de terminaison API.\\n',
  '\\nAdd Connection\\n' => '\\nAjouter une connexion\\n',
  '\\nConfigure authentication (API Key, Bearer Token, or Basic Auth) if your API requires it.\\n' => '\\nConfigurez l\'authentification (clé API, jeton de porteur ou authentification de base) si votre API l\'exige.\\n',
  'Authentication' => 'Authentification',
  '\\nSelect a form and map API response fields to your form fields for auto-populate.\\n' => '\\nSélectionnez un formulaire et mappez les champs de réponse de l\'API à vos champs de formulaire pour un remplissage automatique.\\n',
  '\\nUse the Test button to verify the API returns expected data, then save your connection.\\n' => '\\nUtilisez le bouton Test pour vérifier que l\'API renvoie les données attendues, puis enregistrez votre connexion.\\n',
  '\\nTest & Save\\n' => '\\nTester et enregistrer\\n',
  '\\nUse cache settings to reduce API calls and improve performance.\', \'en\']]' => '\\nUtilisez les paramètres de cache pour réduire les appels d\'API et améliorer les performances.\', \'fr\']]',
  'Performance' => 'Performances',
  '\\nSet a reasonable timeout to prevent slow form loading.\\n' => '\\nDéfinissez un délai d\'expiration raisonnable pour éviter un chargement lent du formulaire.\\n',
  '\\nAlways use HTTPS endpoints for secure data transfer.\\n' => '\\nUtilisez toujours des points de terminaison HTTPS pour un transfert de données sécurisé.\\n',
  '\\nKeep API keys confidential — they are stored securely in WordPress.\', \'tr\']]' => '\\nGardez la confidentialité des clés API : elles sont stockées en toute sécurité dans WordPress.\', \'tr\']]',
  '\\nAPI responses are fetched in real-time when the form loads. Enable caching for frequently accessed data.\\n' => '\\nLes réponses API sont récupérées en temps réel lors du chargement du formulaire. Activer la mise en cache pour les données fréquemment consultées.\\n',
  '\\nAdd New API Connection\\n' => '\\nAjouter une nouvelle connexion API\\n',
