  '\\nFlux Forms WordPress Plugin\\n' => '\\nPlugin WordPress Flux Forms\\n',
  '\\nThis form requires a payment method. Please add one or change the form type.\\n' => '\\nCe formulaire nécessite un mode de paiement. Veuillez en ajouter un ou modifier le type de formulaire.\\n',
  '\\nError Monitor\\n' => '\\nMoniteur d\'erreurs\\n',
