  '\\nfield\\x00fields\\n' => '[[\'field\', \'fr\']]' . chr(0) . '[[\'fields\', \'fr\']]',
  '\\nFlux Donate is not active and the Stripe keys are missing:%dpayment form shows "Online payment is unavailable".\\x00Flux Donate is not active and the Stripe keys are missing:%dpayment forms show "Online payment is unavailable".\\n' => '[[\'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : le formulaire de paiement%daffiche "Le paiement en ligne n\'est pas disponible".\', \'fr\']]' . chr(0) . '[[\'Flux Donate n\'est pas actif et les clés Stripe sont manquantes : les formulaires de paiement%dindiquent "Le paiement en ligne n\'est pas disponible".\', \'fr\']]',
  '\\nNot active, but%dactive automation creates or sends certificates; it will fail.\\x00Not active, but%dactive automations create or send certificates; they will fail.\\n' => '[[\'Non actif, mais l\'automatisation active%dcrée ou envoie des certificats ; ça va échouer.\', \'fr\']]' . chr(0) . '[[\'Non actif, mais les automatisations actives%dcréent ou envoient des certificats ; ils échoueront.\', \'fr\']]',
