  'Flux Forms is an intuitive and user-friendly tool that lets you create custom, multi-step forms in just minutes, without requiring any coding skills.' => '\\nFlux Forms est un outil intuitif et convivial qui vous permet de créer des formulaires personnalisés en plusieurs étapes en quelques minutes seulement, sans nécessiter aucune compétence en codage.\\n',
