  'Switch to Free Plus?' => '[[\'Passer à Free Plus ?\\n',
  'Your Pro activation code will be removed from this site. Pro add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => '\\nVotre code d\'activation Pro sera supprimé de ce site. Les modules complémentaires Pro ne seront pas disponibles jusqu\'à ce que vous effectuiez une nouvelle mise à niveau. Vos formulaires, entrées et paramètres ne seront pas supprimés.\\n',
  'Switch to Free?' => '\\nPasser en version gratuite ?\\n',
  'Advanced features and advanced fields used in your forms will be disabled. Your forms, entries and settings will not be deleted, and will be available again if you upgrade.' => '\\nLes fonctionnalités avancées et les champs avancés utilisés dans vos formulaires seront désactivés. Vos formulaires, entrées et paramètres ne seront pas supprimés et seront à nouveau disponibles si vous effectuez une mise à niveau.\\n',
  'Your Pro activation code will be removed from this site. Advanced features, Pro fields and add-ons will be unavailable until you upgrade again. Your forms, entries and settings will not be deleted.' => '\\nVotre code d\'activation Pro sera supprimé de ce site. Les fonctionnalités avancées, les champs Pro et les modules complémentaires ne seront pas disponibles jusqu\'à ce que vous effectuiez une nouvelle mise à niveau. Vos formulaires, entrées et paramètres ne seront pas supprimés.\\n',
