  'It is not possible to include reCAPTCHA on payment forms.' => '\\nIl n\'est pas possible d\'inclure reCAPTCHA sur les formulaires de paiement.\\n',
  'This site can send emails' => '\\nCe site peut envoyer des e-mails\\n',
  'Weekly email health and form activity report' => '\\nRapport hebdomadaire sur l\'état des e-mails et l\'activité des formulaires\\n',
  'Adds your form activity totals &ndash; forms, views and submissions &ndash; to the weekly email your site sends the main administrator. These totals are read on your own site and are never sent to WhiteStudio.' => '\\nAjoute le total de vos activités de formulaire (formulaires, vues et soumissions) à l\'e-mail hebdomadaire que votre site envoie à l\'administrateur principal. Ces totaux sont lus sur votre propre site et ne sont jamais envoyés à WhiteStudio.\\n',
  'No automated email check has run yet.' => '\\nAucune vérification automatique des e-mails n\'a encore été exécutée.\\n',
  'Collect email delivery statistics' => '\\nCollecter des statistiques de livraison d\'e-mails\\n',
  'Counts how many emails were sent or failed, shows them in the dashboard widget, and adds the email delivery status section to the weekly email. Once a week your site runs a delivery test and reports the result. Only Pro users can turn this off.' => '\\nCompte le nombre d\'e-mails envoyés ou ayant échoué, les affiche dans le widget du tableau de bord et ajoute la section d\'état de livraison des e-mails à l\'e-mail hebdomadaire. Une fois par semaine, votre site effectue un test de livraison et rapporte le résultat. Seuls les utilisateurs Pro peuvent désactiver cette fonctionnalité.\\n',
  'Interval' => '\\nIntervalle\\n',
  'Next Billing Date' => '[[\'Date de facturation suivante\\n',
  'Yearly' => '\\nAnnuelle\\n',
  'How to activate the Pro version of Flux Forms' => '\\nComment activer la version Pro de Flux Forms\\n',
  'Uploaded File' => '\\nFichier téléchargé\\n',
  'Your internet connection has been lost, but do not worry, we have saved the information you entered on this form. Once you are reconnected to the internet, you can easily send your information by clicking the submit button.' => '\\nVotre connexion Internet a été perdue, mais ne vous inquiétez pas, nous avons enregistré les informations que vous avez saisies sur ce formulaire. Une fois que vous êtes reconnecté à Internet, vous pouvez facilement envoyer vos informations en cliquant sur le bouton Soumettre.\\n',
  'Please ensure that you have a stable internet connection and try again.' => '\\nVeuillez vous assurer que vous disposez d\'une connexion Internet stable et réessayer.\\n',
  'There was a problem uploading the file and the form was not submitted. Please check that your internet connection is stable and try again.' => '\\nUn problème est survenu lors du téléchargement du fichier et le formulaire n\'a pas été soumis. Veuillez vérifier que votre connexion Internet est stable et réessayer.\\n',
  'You are experiencing issues with jQuery. Please contact the administrator for assistance. (Error code: JQ-500)' => '\\nVous rencontrez des problèmes avec jQuery. Veuillez contacter l\'administrateur pour obtenir de l\'aide. (Code d\'erreur : JQ-500)\\n',
  'Your session has expired. Please refresh the page and try again.' => '\\nVotre session a expiré. Veuillez actualiser la page et réessayer.\\n',
  'Basic' => '\\nBasique\\n',
  'Sign-In|Up' => '\\nConnexion|Se connecter\\n',
  'Advance' => '\\nAvance\\n',
  'Thank you Page' => '\\nMerci Page\\n',
  'Redirect page' => '\\nPage de redirection\\n',
  'Please wait, you will be redirected shortly.' => '\\nVeuillez patienter, vous serez redirigé sous peu.\\n',
  'Persia payment' => '\\nPaiement Perse\\n',
  'Unlock Pro Features Today' => '[[\'Débloquez les fonctionnalités Pro aujourd\'hui\\n',
  'Upgrade to Pro for just %1$s%2$s%3$s/year and get access to powerful features, including advanced form fields, payment integrations, conditional logic, multi-step forms, file uploads, Security & Spam Protection, and priority support.%4$sView Pro Features%5$s' => '\\n Passez à Pro pour seulement%1$s%2$s%3$s/ an et accédez à des fonctionnalités puissantes, notamment des champs de formulaire avancés, des intégrations de paiement, une logique conditionnelle, des formulaires en plusieurs étapes, des téléchargements de fichiers, la sécurité et la protection anti-spam et une assistance prioritaire.%4$sAfficher les fonctionnalités Pro%5$s\\n',
  'Add-on' => '\\nModule complémentaire\\n',
  'Add-ons' => '\\nModules complémentaires\\n',
  'Stripe Payment Add-on' => '[[\'Module complémentaire de paiement Stripe\\n',
  'The Stripe add-on for Flux Forms enables you to integrate your WordPress site with Stripe for payment processing, donations, and online orders.' => '\\nLe module complémentaire Stripe pour Flux Forms vous permet d\'intégrer votre site WordPress à Stripe pour le traitement des paiements, les dons et les commandes en ligne.\\n',
  'Offline Forms Add-on' => '[[\'Module complémentaire Formulaires hors ligne\\n',
  'The Offline Forms add-on for Flux Forms allows users to save their progress when filling out forms in offline situations.' => '\\nLe module complémentaire Offline Forms pour Flux Forms permet aux utilisateurs d\'enregistrer leur progression lorsqu\'ils remplissent des formulaires dans des situations hors ligne.\\n',
  'Please update Flux Forms before trying again.' => '[["Veuillez mettre à jour Flux Forms avant de réessayer.\\n',
  'Activation of offline form mode.' => '\\nActivation du mode formulaire hors ligne.\\n',
  'Before activating this option, install' => '\\nAvant d\'activer cette option, installez\\n',
  'To create a payment form to collect online payments, you must first install a payment add-on such as the Stripe Add-on.' => '\\nPour créer un formulaire de paiement permettant de collecter des paiements en ligne, vous devez d\'abord installer un module complémentaire de paiement tel que le module complémentaire Stripe.\\n',
  'All formats' => '\\nTous les formats\\n',
  'EFB SMS Add-on' => '\\nModule complémentaire SMS EFB\\n',
  'Enable SMS functionality in your forms with the EFB SMS add-on, allowing you to validate mobile numbers and send confirmation codes via SMS, as well as receive notifications through SMS service.' => '\\nActivez la fonctionnalité SMS dans vos formulaires avec le module complémentaire EFB SMS, vous permettant de valider des numéros de mobile et d\'envoyer des codes de confirmation par SMS, ainsi que de recevoir des notifications via le service SMS.\\n',
  'Advanced confirmation code Add-on' => '\\nModule complémentaire de code de confirmation avancé\\n',
  'Send a confirmation code via email or SMS to users and/or admins, allowing them to quickly access new responses.' => '\\nEnvoyez un code de confirmation par e-mail ou SMS aux utilisateurs et/ou administrateurs, leur permettant d\'accéder rapidement aux nouvelles réponses.\\n',
  'Box Checklist' => '\\nListe de contrôle des cases\\n',
  'Radio Checklist' => '\\nListe de contrôle radio\\n',
  'This is a warning for WPBakery users. For more information, please click here.' => '\\nCeci est un avertissement pour les utilisateurs de WPBakery. Pour plus d\'informations, veuillez cliquer ici.\\n',
  'Are you sure you want to close replies to this message?' => '\\nÊtes-vous sûr de vouloir fermer les réponses à ce message ?\\n',
  'Are you sure you want to open the responses to this message?' => '\\nÊtes-vous sûr de vouloir ouvrir les réponses à ce message ?\\n',
