  'Screen recording is not supported on this device or browser (most mobile browsers do not allow it). Please open the form in a desktop browser such as Chrome, Edge or Firefox.' => '\\nL\'enregistrement d\'écran n\'est pas pris en charge sur cet appareil ou ce navigateur (la plupart des navigateurs mobiles ne le permettent pas). Veuillez ouvrir le formulaire dans un navigateur de bureau tel que Chrome, Edge ou Firefox.\\n',
