  'The entered data does not match the form type. If you are an admin, please review the form type.' => '\\nLes données saisies ne correspondent pas au type de formulaire. Si vous êtes un administrateur, veuillez vérifier le type de formulaire.\', \'fr\']]',
  'Error: Please ensure there is only one form per page.' => '\\nErreur : Veuillez vous assurer qu\'il n\'y a qu\'un seul formulaire par page.\\n',
  'Your activation code has been verified. Enjoy all Pro features of Flux Forms.' => '\\nVotre code d\'activation a été vérifié. Profitez de toutes les fonctionnalités Pro de Flux Forms.", \'fr\']]',
  'The confirmation code for this message is %s. By clicking the button below, you will be able to track messages and view received responses. If needed, you can also send a new reply.' => '\\nLe code de confirmation de ce message est%s. En cliquant sur le bouton ci-dessous, vous pourrez suivre les messages et afficher les réponses reçues. Si nécessaire, vous pouvez également envoyer une nouvelle réponse.\\n',
  'To explore the full functionality and settings of Flux Forms, including email configurations, form creation options, and other features, simply delve into our %1$s documentation %2$s .' => '\\nPour explorer toutes les fonctionnalités et paramètres de Flux Forms, y compris les configurations de messagerie, les options de création de formulaires et d\'autres fonctionnalités, plongez simplement dans notre documentation%1$s%2$s.\\n',
  'Responses & Confirmation' => '\\nRéponses et confirmation\\n',
  'Test emails may land in your spam folder. If emails are not delivered, this is usually related to your hosting or email server configuration.server settings %1$sLearn how to fix email delivery issues%2$s or %3$scontact Flux Forms support%4$s.' => '\\nLes e-mails de test peuvent atterrir dans votre dossier spam. Si les e-mails ne sont pas livrés, cela est généralement lié à la configuration de votre hébergement ou de votre serveur de messagerie. Paramètres du serveur%1$sDécouvrez comment résoudre les problèmes de livraison des e-mails%2$sou%3$scontactez l\'assistance Flux Forms%4$s.\\n',
  'From Address' => '\\nAdresse d\'origine\\n',
  'Make sure this email address matches the one configured in your SMTP settings to prevent email delivery issues.' => '\\nAssurez-vous que cette adresse e-mail correspond à celle configurée dans vos paramètres SMTP pour éviter les problèmes de livraison des e-mails.\\n',
  'To preview the form, you need to save the built form and try again.' => '\\nPour prévisualiser le formulaire, vous devez enregistrer le formulaire créé et réessayer.\\n',
  'No selected rows found.' => '\\nAucune ligne sélectionnée trouvée.\\n',
  'Mark as Read' => '\\nMarquer comme lu\\n',
  'Require admin login to view responses' => '\\nExiger une connexion administrateur pour afficher les réponses\\n',
  'Development Mode (Sandbox)' => '\\nMode développement (bac à sable)\\n',
  'When enabled, uses sandbox/demo servers for PayPal and other services. Disable for production.' => '\\nLorsqu\'il est activé, utilise des serveurs sandbox/démo pour PayPal et d\'autres services. Désactiver pour la production.\\n',
  'After changing the Development Mode (Sandbox) option, save the settings, then deactivate and reactivate Flux Forms plugin from the Plugins page for the changes to take effect.' => '\\nAprès avoir modifié l\'option Mode de développement (Sandbox), enregistrez les paramètres, puis désactivez et réactivez le plugin Flux Forms depuis la page Plugins pour que les modifications prennent effet.\\n',
  'I have read and agree to %1$sthe terms and conditions%2$s' => '\\nJ\'ai lu et j\'accepte%1$sles termes et conditions%2$s\\n',
  'Terms' => '\\nConditions\\n',
  'Preview in new tab' => '\\nAperçu dans un nouvel onglet\\n',
  'Maximum date' => '\\nDate maximale\\n',
  'Minimum date' => '\\nDate minimale\\n',
  'Valid formats: %s' => '\\nFormats valides :%s\\n',
  'Zoom' => '\\nZoom\\n',
  'The map library (OpenStreetMap and Leaflet) loads only on pages that contain a location picker field.' => '\\nLa bibliothèque de cartes (OpenStreetMap et Leaflet) se charge uniquement sur les pages contenant un champ de sélection d\'emplacement.\\n',
  'Enable Location Picker in Flux Forms' => '\\nActiver le sélecteur d\'emplacement dans Flux Forms\\n',
  'Flux Forms cannot display the form because jQuery is not properly loaded. This issue might be due to incorrect jQuery invocation by another plugin or the current website theme.' => '\\nFlux Forms ne peut pas afficher le formulaire car jQuery n\'est pas correctement chargé. Ce problème peut être dû à un appel jQuery incorrect par un autre plugin ou au thème actuel du site Web.\\n',
  'Telegram Notification Add-on' => '\\nModule complémentaire de notification par télégramme\\n',
  'The Telegram notification add-on lets you get notifications on your Telegram app whenever you receive new messages or responses' => '\\nLe module complémentaire de notification Telegram vous permet de recevoir des notifications sur votre application Telegram chaque fois que vous recevez de nouveaux messages ou réponses\\n',
  'Enter a location name' => '\\nEntrez un nom d\'emplacement\\n',
  'The %1$s pages are currently unavailable. It looks like another plugin is causing a conflict with %1$s . To fix this issue, %2$s contact %1$s support %3$s for assistance or try disabling your plugins one at a time to identify the one causing the conflict.' => '\\nLes pages%1$ssont actuellement indisponibles. Il semble qu\'un autre plugin provoque un conflit avec%1$s. Pour résoudre ce problème,%2$scontactez l\'assistance%1$s%3$spour obtenir de l\'aide ou essayez de désactiver vos plug-ins un par un pour identifier celui à l\'origine du conflit.\\n',
  'Send email with submitted form content only' => '[[\'Envoyer un e-mail contenant uniquement le contenu du formulaire soumis\\n',
  '%s copied!' => '\\n%scopié !\\n',
  'The website is not responding; please refresh and try again—saving or submitting is not available until it is restored.' => '\\nLe site Web ne répond pas ; veuillez actualiser et réessayer : l\'enregistrement ou la soumission ne sont pas disponibles tant qu\'ils ne sont pas restaurés.\\n',
  'Your session has expired or is no longer valid. Please refresh the page to continue.' => '\\nVotre session a expiré ou n\'est plus valide. Veuillez actualiser la page pour continuer.\\n',
  'Your account has been successfully activated. You can now log in and get started!' => '\\nVotre compte a été activé avec succès. Vous pouvez maintenant vous connecter et commencer !\\n',
  'You\'re all done' => '\\nVous avez terminé\\n',
  'Enter your email to reset your password' => '\\nEntrez votre email pour réinitialiser votre mot de passe\\n',
  'If your email is valid, a password reset link has been sent to your email address.' => '\\nSi votre adresse e-mail est valide, un lien de réinitialisation de mot de passe a été envoyé à votre adresse e-mail.\\n',
  'Enable %s' => '\\nActiver%s\\n',
  'Auto-Populate' => '\\nRemplir automatiquement\\n',
  'Auto-populate from previously submitted forms' => '\\nRemplir automatiquement à partir des formulaires précédemment soumis\', \'fr\']]',
  'Enable Auto-Populate to automatically populate this field' => '\\nActivez le remplissage automatique pour remplir automatiquement ce champ\\n',
  'API Auto-Populate Integration is Active' => '\\nL\'intégration du remplissage automatique de l\'API est active\\n',
  'This form uses External API Auto-Populate. To configure settings, go to' => '\\nCe formulaire utilise le remplissage automatique de l\'API externe. Pour configurer les paramètres, accédez à\\n',
  'Auto-Populate Integrations' => '\\nIntégrations à remplissage automatique\\n',
