  'Submitted Form' => '\\nFormulaire soumis\\n',
  'You can\'t add reCAPTCHA to payment forms.' => '\\nVous ne pouvez pas ajouter reCAPTCHA aux formulaires de paiement.\\n',
  'Learn more about %s or watch the video tutorial.' => '\\nApprenez-en plus sur%sou regardez le didacticiel vidéo.\\n',
  'Learn more %s' => '\\nEn savoir plus%s\\n',
  'Google reCAPTCHA' => '\\nGoogle reCAPTCHA\\n',
  'The connection was interrupted, but don\'t worry—your edits are safely stored in your browser. Refresh the page to continue working.' => '\\nLa connexion a été interrompue, mais ne vous inquiétez pas : vos modifications sont stockées en toute sécurité dans votre navigateur. Actualisez la page pour continuer à travailler.\\n',
  'There is an auto-saved version of the form available. Do you want to restore it?' => '[["Une version enregistrée automatiquement du formulaire est disponible. Voulez-vous la restaurer ?\\n',
  'SMS notification could not be sent. Check if the SMS plugin is installed and configured properly.' => '\\nLa notification par SMS n\'a pas pu être envoyée. Vérifiez si le plug-in SMS est installé et configuré correctement.\\n',
  'Your request was completed successfully. %1$s %2$s' => '\\nVotre demande a été complétée avec succès.%1$s%2$s\\n',
  'PayPal' => '\\nPayPal\\n',
  'To use %1$s features in your forms, you need to get your %2$s keys.' => '\\nPour utiliser les fonctionnalités%1$sdans vos formulaires, vous devez obtenir vos clés%2$s.\\n',
  'Go to the add-ons page in the Flux Forms plugin, install the %s add-on, and try again.' => '\\nAccédez à la page des modules complémentaires du plug-in Flux Forms, installez le module complémentaire%set réessayez.\\n',
  'To create a payment form to collect online payments, install a payment add-on such as the %s Add-on first.' => '\\nPour créer un formulaire de paiement permettant de collecter des paiements en ligne, installez d\'abord un module complémentaire de paiement tel que le module complémentaire%s.\\n',
  'Thank' => '\\nMerci\\n',
  'The %s plugin may interfere with Flux Forms form functionality. If you encounter any issues with the forms, disable caching for the Flux Forms plugin in the %s settings.' => '\\nLe plugin%speut interférer avec la fonctionnalité des formulaires Flux Forms. Si vous rencontrez des problèmes avec les formulaires, désactivez la mise en cache du plug-in Flux Forms dans les paramètres%s.\\n',
  'Remind me later' => '\\nRappelez-moi plus tard\\n',
  'Got it, don\'t show again' => '[["Compris, ne le montre plus\\n',
  'The value of the %1$s field does not match the pattern and must be at least %2$s characters.' => '\\nLa valeur du champ%1$sne correspond pas au modèle et doit contenir au moins des caractères%2$s.\\n',
  'The value of the %1$s field does not match the pattern and must be at most %2$s characters.' => '\\nLa valeur du champ%1$sne correspond pas au modèle et doit contenir au maximum des caractères%2$s.\\n',
  'Please enter valid value for the %s field.' => '[[\'Veuillez saisir une valeur valide pour le champ%s.\\n',
  '%s list' => '\\n%sliste\\n',
  'The uploaded file exceeds the allowable limit of %s MB.' => '\\nLe fichier téléchargé dépasse la limite autorisée de%sMo.\\n',
  'The uploaded file is below the required minimum size of %s MB.' => '\\nLe fichier téléchargé est inférieur à la taille minimale requise de%sMo.\\n',
  'Review the entered values in the %s tab. This message appeared because an error was detected.' => '\\nVérifiez les valeurs saisies dans l\'onglet%s. Ce message est apparu car une erreur a été détectée.\\n',
  'Are you sure you want to duplicate the "%s" ?' => '\\nÊtes-vous sûr de vouloir dupliquer le "%s" ?\\n',
  'We are sorry, the booking time for the %s option has expired. Please choose from the other available options.' => '\\nNous sommes désolés, le délai de réservation pour l\'option%sa expiré. Veuillez choisir parmi les autres options disponibles.\\n',
  'We are sorry, the %s option is currently at full capacity. Please choose from the other available options.' => '\\nNous sommes désolés, l\'option%sest actuellement à pleine capacité. Veuillez choisir parmi les autres options disponibles.\\n',
  '%s Payment Add-on' => '\\n Module complémentaire de paiement%s\\n',
  'The %s add-on for Flux Forms enables you to integrate your WordPress site with %s for payment processing, donations, and online orders.' => '\\nLe module complémentaire%spour Flux Forms vous permet d\'intégrer votre site WordPress à%spour le traitement des paiements, les dons et les commandes en ligne.\\n',
  'Activation Code' => '\\nCode d\'activation\\n',
  'Want to use this feature? It is included in Free Plus and Pro plans.' => '\\nVous souhaitez utiliser cette fonctionnalité ? Il est inclus dans les forfaits Free Plus et Pro.\\n',
  'Free Plus Guide' => '\\nGuide Plus gratuit\\n',
  'A Pro version feature' => '\\nUne fonctionnalité de la version Pro\', \'fr\']]',
  'Free Plus unlocks this too' => '\\nFree Plus débloque également cela\\n',
  'Unlocked by a free activation, which is enough for this feature.' => '\\nDébloqué par une activation gratuite, suffisante pour cette fonctionnalité.\\n',
  'Every feature, with no limits, and support included.' => '\\nToutes les fonctionnalités, sans limites et support inclus.\\n',
  'Search Results' => '\\nRésultats de la recherche\\n',
  'Found %s %s for: "%s"' => '\\n%s%strouvé pour : "%s"\\n',
  'results' => '\\nrésultats\\n',
  'No results found for:' => '\\nAucun résultat trouvé pour :\', \'fr\']]',
  'Found %1$s %2$s for' => '\\n%1$s%2$strouvé pour\\n',
  'Session Duration' => '\\nDurée de la session\\n',
  'Set how long form security tokens remain valid. Longer durations provide better user experience but may reduce security.' => '\\nDéfinissez la durée pendant laquelle les jetons de sécurité du formulaire restent valides. Des durées plus longues offrent une meilleure expérience utilisateur mais peuvent réduire la sécurité.\\n',
