  'Protection is paused.' => '\\nLa protection est suspendue.\\n',
  'Fix system requirements before protection can run.' => '\\nCorrigez la configuration système requise avant que la protection puisse s\'exécuter.\\n',
  'Behavior checks and rate limits are running.' => '\\nLes contrôles de comportement et les limites de débit sont en cours d\'exécution.\\n',
  'Quarantined' => '\\nEn quarantaine\\n',
