  'Submit score' => '\\nSoumettre le score\\n',
  'Paid notification score' => '\\nScore de notification payante\', \'fr\']]',
  'Token TTL' => '\\nJeton TTL\\n',
  'IP submit/min' => '\\nSoumission IP/min\\n',
  'Response add/min' => '\\nRéponse ajoutée/min\\n',
  'Request protection' => '\\nDemander une protection\\n',
  'Controls that run before EFB REST callbacks.' => '\\nContrôles exécutés avant les rappels EFB REST.\\n',
  'Enable Human Shield' => '\\nActiver le Bouclier humain\\n',
  'Activate behavior tokens and rate limits.' => '\\nActivez les jetons de comportement et les limites de débit.\\n',
  'Monitor logs only; soft block is recommended for production rollout.' => '\\nSurveiller les journaux uniquement ; le bloc logiciel est recommandé pour le déploiement en production.\\n',
  'Minimum submit score' => '\\nScore de soumission minimum\\n',
