  'Token TTL seconds' => '\\nJeton TTL secondes\\n',
  'Short-lived single-use human token.' => '\\nJeton humain à usage unique de courte durée.\\n',
  'Challenge TTL seconds' => '\\nDéfiez les secondes TTL\\n',
  'How long a browser challenge can stay open.' => '[[\'Combien de temps un défi de navigateur peut rester ouvert.\\n',
  'All API requests per IP/min' => '\\nToutes les requêtes API par IP/min\\n',
  'Global application-layer backstop.' => '\\nGarantie de sécurité mondiale au niveau de la couche d\'application.\\n',
  'Submits per IP/min' => '\\nEnvois par IP/min\\n',
  'Per-IP submit limit.' => '\\nLimite de soumission par IP.\\n',
