  'Longer per-IP submit limit.' => '\\nLimite de soumission par IP plus longue.\\n',
  'Form global/min' => '\\nFormulaire global/min\\n',
  'Total submit pressure per form.' => '[[\'Pression de soumission totale par formulaire.\\n',
  'Tracking lookups per IP/min' => '\\nSuivi des recherches par IP/min\\n',
  'Protects confirmation-code lookup.' => '\\nProtège la recherche de code de confirmation.\\n',
  'Responses per IP/min' => '\\nRéponses par IP/min\\n',
  'Protects public reply box.' => '\\nProtège la boîte de réponse publique.\\n',
  'Replies per tracking code/hour' => '\\nRéponses par code de suivi/heure\\n',
  'Caps replies to one tracked conversation (across IPs). 0 disables.' => '\\nCaps les réponses à une conversation suivie (sur les adresses IP). 0 désactive.\\n',
  'Uploads per IP/min' => '\\nTéléchargements par IP/min\\n',
  'Protects upload endpoint.' => '\\nProtège le point de terminaison de téléchargement.\\n',
  'Payment starts per IP/min' => '\\nLe paiement commence par IP/min\\n',
  'Protects payment REST routes.' => '\\nProtège les itinéraires de paiement REST.\\n',
  'File upload budget' => '\\nBudget de téléchargement de fichiers\\n',
  'Flux Forms already limits uploads on its own: each visitor may upload three files per file field on the form, and the response box allows three. Leave a box at 0 to keep that automatic behaviour, or enter a number to set it yourself.' => '\\nFlux Forms limite déjà les téléchargements : chaque visiteur peut télécharger trois fichiers par champ de fichier sur le formulaire, et la zone de réponse en autorise trois. Laissez une case à 0 pour conserver ce comportement automatique, ou entrez un nombre pour le définir vous-même.\\n',
  'Uploads allowed per file field' => '\\nTéléchargements autorisés par champ de fichier\\n',
  'Default 3, so a two-field form allows six uploads. 0 keeps the default.' => '\\nPar défaut 3, donc un formulaire à deux champs autorise six téléchargements. 0 conserve la valeur par défaut.\\n',
  'Total uploads per visitor' => '\\nTotal des téléchargements par visiteur\\n',
  'A fixed total that ignores how many fields the form has. 0 keeps the automatic per-field calculation.' => '\\nUn total fixe qui ignore le nombre de champs du formulaire. 0 conserve le calcul automatique par champ.\\n',
  'Budget resets after (seconds)' => '\\nLe budget est réinitialisé après (secondes)\\n',
  'Default 3600 (one hour). 0 keeps the default.' => '\\nPar défaut 3 600 (une heure). 0 conserve la valeur par défaut.\\n',
  'Maximum file size (MB)' => '\\nTaille maximale du fichier (Mo)\\n',
  'A site-wide ceiling. It can only tighten a per-field limit, never widen it. 0 keeps the field setting.' => '\\nUn plafond à l\'échelle du site. Il ne peut que resserrer une limite par champ, jamais l\'élargir. 0 conserve le paramètre du champ.\\n',
  'Protect response lookup' => '\\nProtéger la recherche de réponse\\n',
  'Rate-limit tracking-code searches by request count (no human-token check).' => '\\nRecherches de code de suivi avec limite de débit par nombre de requêtes (pas de vérification de jeton humain).\\n',
  'Manual access lists' => '\\nListes d\'accès manuel\\n',
  'One entry per line: an exact IP or a wildcard prefix such as 203.0.113.* — allowlist bypasses all checks, blocklist blocks in every mode.' => '\\nUne entrée par ligne : une adresse IP exacte ou un préfixe générique tel que 203.0.113.* — la liste autorisée contourne toutes les vérifications, la liste de blocage bloque dans tous les modes.\\n',
  'IP allowlist' => '[[\'Liste d\'adresses IP autorisées\\n',
  'Trusted IPs that skip the shield completely (your office, monitoring bots).' => '\\nIPs de confiance qui ignorent complètement le bouclier (votre bureau, surveillance des robots).\\n',
  'IP blocklist' => '\\nListe de blocage des adresses IP\\n',
  'IPs that are always blocked on protected form routes.' => '\\nIP qui sont toujours bloquées sur les routes de formulaire protégées.\\n',
  'Minimum paid notification score' => '\\nScore minimum de notification payante\\n',
  'Suppress costly notifications below this score.' => '\\nSupprimez les notifications coûteuses en dessous de ce score.\\n',
  'SMS daily stop-loss' => '[["Stop-loss quotidien par SMS\\n',
  'Global SMS budget per day, across all recipients.' => '\\nBudget SMS global par jour, pour tous les destinataires.\\n',
  'Telegram daily stop-loss' => '\\nTelegram stop-loss quotidien\\n',
  'Global Telegram budget per day, across all recipients.' => '\\nBudget Telegram global par jour, pour tous les destinataires.\\n',
  'Webhook/Email daily stop-loss' => '\\nWebhook/E-mail stop-loss quotidien\\n',
  'Global webhook/email/sheet budget per day.' => '\\nBudget global de webhook/e-mail/feuille par jour.\\n',
  'Per-recipient daily cap' => '\\nPlafond quotidien par destinataire\\n',
  'Maximum notifications per single recipient per day (0 disables).' => '\\nNotifications maximales par destinataire unique et par jour (0 désactivé).\\n',
  'These limits become active for paid services after the core integration filter is added.' => '\\nCes limites deviennent actives pour les services payants après l\'ajout du filtre d\'intégration principal.\\n',
  'Decisions — last 24 hours' => '\\nDécisions — dernières 24 heures\\n',
  'Stacked per hour: allowed, blocked, quarantined and monitored requests.' => '\\nStacked par heure : demandes autorisées, bloquées, mises en quarantaine et surveillées.\\n',
  'No decisions recorded in the last 24 hours.' => '\\nAucune décision enregistrée au cours des dernières 24 heures.\\n',
  'Security logs' => '\\nJournaux de sécurité\\n',
