  'If a required PHP function is disabled, enable it in php.ini disable_functions or ask the host to allow it. Cache and security plugins must not cache or rewrite POST responses from /wp-json/EmsfbShield/v1/*.' => '\\nSi une fonction PHP requise est désactivée, activez-la dans php.ini Disable_functions ou demandez à l\'hôte de l\'autoriser. Les plugins de cache et de sécurité ne doivent pas mettre en cache ou réécrire les réponses POST de /wp-json/EmsfbShield/v1/*.\\n',
  'Security & Spam Protection tabs' => '\\nOnglets Sécurité et protection anti-spam\\n',
