  'WPBakery form plugin' => '\\nPlugin de formulaire WPBakery\\n',
  'Some plugin files are missing, so the plugin stopped loading to keep your site running. Please reinstall Flux Forms from the Plugins page — your forms, messages, and settings are kept.' => '\\nCertains fichiers du plugin sont manquants, le plugin a donc arrêté de se charger pour que votre site continue de fonctionner. Veuillez réinstaller Flux Forms à partir de la page Plugins : vos formulaires, messages et paramètres sont conservés.\\n',
  'Missing files:' => '\\nFichiers manquants :\\n',
  'Select a form to display from the dropdown below.' => '\\nSélectionnez un formulaire à afficher dans la liste déroulante ci-dessous.\\n',
