  'Form will be displayed here on the frontend.' => '\\nLe formulaire sera affiché ici sur le frontend.\\n',
  'Loading forms&hellip;' => '\\nChargement des formulaires...\\n',
  '📍 Confirmation Code Finder (Tracking Form)' => '[[\'📍 Recherche de code de confirmation (formulaire de suivi)\\n',
  'Choose a form to display. The tracking form allows users to find submissions by confirmation code.' => '\\nChoisissez un formulaire à afficher. Le formulaire de suivi permet aux utilisateurs de rechercher les soumissions par code de confirmation.\\n',
