  'Selected Form ID:' => '\\nID du formulaire sélectionné :\\n',
  'The form will appear here on the frontend.' => '\\nLe formulaire apparaîtra ici sur le frontend.\\n',
  'Display an Flux Forms form' => '\\nAfficher un formulaire Flux Forms\\n',
  'Display the form name as a heading above the form.' => '\\nAffichez le nom du formulaire sous forme d\'en-tête au-dessus du formulaire.\\n',
  'Extra Class Name' => '\\nNom de classe supplémentaire\\n',
  'Add custom CSS classes for styling.' => '\\nAjouter des classes CSS personnalisées pour le style.\', \'fr\']]',
  'Design' => '\\nConception\\n',
  'CSS' => '\\nCSS\\n',
  'Select a form from the element settings.' => '\\nSélectionnez un formulaire dans les paramètres de l\'élément.\\n',
  '✏️ Click to edit and choose a form' => '\\n✏️ Cliquez pour modifier et choisir un formulaire\\n',
  'Add forms created with Flux Forms' => '[[\'Ajouter des formulaires créés avec Flux Forms\\n',
  'Display Flux Forms forms on your page' => '\\nAfficher les formulaires Flux Forms sur votre page\\n',
  'Choose the form you want to display' => '\\nChoisissez le formulaire que vous souhaitez afficher\\n',
  'Please select a form from element settings' => '\\nVeuillez sélectionner un formulaire dans les paramètres de l\'élément\\n',
  'Form: %s (ID: %s)' => '\\nFormulaire :%s(ID :%s)\\n',
  '📍 Confirmation Code Finder (Tracking)' => '\\n📍 Recherche de code de confirmation (suivi)\', \'fr\']]',
  '🎨 Flux Forms' => '\\n🎨Formulaires de flux\\n',
  'Add Flux Forms forms to your page' => '\\nAjouter des formulaires Flux Forms à votre page\\n',
  'Select Form:' => '\\nSélectionner un formulaire :\\n',
  'Custom Title (optional):' => '\\nTitre personnalisé (facultatif) :\', \'fr\']]',
  'Shortcode:' => '\\nCode court :\\n',
  'Run the email check' => '\\nExécutez la vérification des e-mails\\n',
  'The last delivery check scored %s out of 100. Your messages do leave the site, but most mailboxes will file them as spam, so the people filling in your forms will not see them. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => '\\nLe dernier contrôle de livraison a noté%ssur 100. Vos messages quittent le site, mais la plupart des boîtes aux lettres les classeront comme spam, donc les personnes remplissant vos formulaires ne les verront pas. L\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine permettent de résoudre ce problème.\\n',
  'The last delivery check found that your messages do leave the site, but mailboxes file them as spam. Sending through an SMTP service, and adding SPF and DKIM records for your domain, is what fixes this.' => '\\nLe dernier contrôle de livraison a révélé que vos messages quittent le site, mais les boîtes aux lettres les classent comme spam. L\'envoi via un service SMTP et l\'ajout d\'enregistrements SPF et DKIM pour votre domaine permettent de résoudre ce problème.\\n',
  'Your form emails are going to the spam folder' => '\\nVos e-mails de formulaire vont dans le dossier spam\\n',
  'Your form emails are sent, but they are not arriving' => '[[\'Vos e-mails de formulaire sont envoyés, mais ils n\'arrivent pas\\n',
  'WordPress sent the last test message successfully, so your site and this plugin did their part - it was lost, delayed or rejected after leaving WordPress. Usually the receiving mailbox treated it as spam, or your host never delivered it from the outbound queue. Sending through an SMTP service, with SPF and DKIM records for your domain, is what fixes this.' => '\\nWordPress a envoyé le dernier message de test avec succès, donc votre site et ce plugin ont fait leur part : il a été perdu, retardé ou rejeté après avoir quitté WordPress. Habituellement, la boîte aux lettres de réception l\'a traité comme du spam, ou votre hôte ne l\'a jamais envoyé depuis la file d\'attente sortante. L\'envoi via un service SMTP, avec des enregistrements SPF et DKIM pour votre domaine, est ce qui résout ce problème.\\n',
  'WordPress cannot send your form emails' => '\\nWordPress ne peut pas envoyer les e-mails de votre formulaire\\n',
  'The last check could not even hand a message to your mail server: WordPress reported an error while sending, so nothing left the site. An SMTP plugin, or asking your host whether PHP mail is disabled, is where to start.' => '\\nLa dernière vérification n\'a même pas permis de transmettre un message à votre serveur de messagerie : WordPress a signalé une erreur lors de l\'envoi, donc rien n\'a quitté le site. Un plugin SMTP, ou demander à votre hôte si la messagerie PHP est désactivée, est par où commencer.\\n',
  'Your form emails are not being delivered' => '\\nVos e-mails de formulaire ne sont pas livrés\', \'fr\']]',
  'The last delivery check could not get a message through, so nothing your forms send is reaching anybody. A hosting server usually sends mail without a trusted signature; sending through an SMTP service is the standard fix.' => '\\nLe dernier chèque de livraison n\'a pas pu faire passer de message, donc rien de ce que vos formulaires envoient ne parvient à personne. Un serveur d\'hébergement envoie généralement du courrier sans signature fiable ; l\'envoi via un service SMTP est la solution standard.\\n',
  'Once Weekly (Flux Forms)' => '\\nUne fois par semaine (Formulaires Flux)\\n',
  'The weekly email delivery test completed successfully.' => '\\nLe test hebdomadaire de livraison des e-mails s\'est terminé avec succès.\\n',
  'The weekly email delivery test found an email delivery problem.' => '\\nLe test hebdomadaire de livraison des e-mails a révélé un problème de livraison des e-mails.\\n',
  'The main WordPress administrator email address is not valid.' => '\\nL\'adresse e-mail principale de l\'administrateur WordPress n\'est pas valide.\\n',
  'Could not start the email delivery test.' => '\\nImpossible de démarrer le test de livraison des e-mails.\\n',
  'WordPress sent the automated test email and is waiting for it to arrive.' => '\\nWordPress a envoyé l\'e-mail de test automatisé et attend qu\'il arrive.\\n',
  'WordPress could not send the automated test email. The message never left this website.' => '\\nWordPress n\'a pas pu envoyer l\'e-mail de test automatisé. Le message n\'a jamais quitté ce site Web.\\n',
  'The email delivery test timed out before confirmation was received.' => '\\nLe test de livraison des e-mails a expiré avant la réception de la confirmation.\\n',
  'Weekly Flux Forms report for %s' => '\\nRapport hebdomadaire Flux Forms pour%s\\n',
  'Here is your weekly snapshot for %s.' => '\\nVoici votre instantané hebdomadaire pour%s.\\n',
  'Report generated %s' => '[[\'Rapport généré%s\\n',
  'Detailed analysis' => '\\nAnalyse détaillée\\n',
  'Emails failed' => '\\nÉchec des e-mails\\n',
  'You can turn these reports off in Flux Forms settings.' => '\\nVous pouvez désactiver ces rapports dans les paramètres de Flux Forms.\\n',
  'The test email was delivered, but its deliverability score is only %1$s out of 100 (below %2$s), so the emails your forms send are very likely to be rejected or filtered as spam.' => '\\nL\'e-mail de test a été envoyé, mais son score de délivrabilité n\'est que de%1$ssur 100 (inférieur à%2$s), donc les e-mails envoyés par vos formulaires sont très susceptibles d\'être rejetés ou filtrés comme spam.\\n',
  'Run the email check so you can be sure the messages your forms send are actually reaching people. The check sends a real message through the new WhiteStudio delivery service and reports back what arrived.' => '\\nExécutez la vérification des e-mails pour être sûr que les messages envoyés par vos formulaires parviennent réellement aux personnes. Le chèque envoie un vrai message via le nouveau service de livraison WhiteStudio et rend compte de ce qui est arrivé.\\n',
  'Read the guide to sending email through SMTP' => '\\nLisez le guide sur l\'envoi d\'e-mails via SMTP\\n',
  'Delivery has not been scored yet' => '\\nLa livraison n\'a pas encore été notée\\n',
  'WordPress sent your email, but it never arrived' => '\\nWordPress a envoyé votre e-mail, mais il n\'est jamais arrivé\\n',
  'WordPress could not send your email' => '\\nWordPress n\'a pas pu envoyer votre email\', \'fr\']]',
  'We could not confirm your emails are being delivered' => '\\nNous n\'avons pas pu confirmer que vos e-mails ont été livrés\\n',
  'out of 100' => '\\nsur 100\\n',
  'Your email delivery is healthy' => '\\nLa diffusion de vos e-mails est saine\\n',
  'Your emails are likely going to spam' => '\\nVos e-mails seront probablement du spam\\n',
  'Your emails are not reaching anybody' => '\\nVos e-mails ne parviennent à personne\\n',
  'grade %s' => '\\ngrade%s\\n',
  'What you should do' => '\\nCe que vous devez faire\\n',
  'A hosting server usually sends mail without a trusted signature, which is what pushes your form emails into the spam folder or stops them arriving at all. The standard fix is to send through an SMTP service.' => '\\nUn serveur d\'hébergement envoie généralement des messages sans signature fiable, ce qui pousse les e-mails de votre formulaire dans le dossier spam ou les empêche d\'arriver. La solution standard consiste à envoyer via un service SMTP.\\n',
  'Install an SMTP plugin and enter the details of your email service.' => '\\nInstallez un plugin SMTP et saisissez les détails de votre service de messagerie.\\n',
  'Add the SPF and DKIM records to your domain settings.' => '\\nAjoutez les enregistrements SPF et DKIM aux paramètres de votre domaine.\\n',
  'Run the email check again until the score is above %s.' => '\\nExécutez à nouveau la vérification des e-mails jusqu\'à ce que le score soit supérieur à%s.\\n',
  'You have %1$s forms: %2$s active and %3$s inactive.' => '\\nVous avez des formulaires%1$s:%2$sactif et%3$sinactif.\\n',
  'Renew Flux Forms Pro' => '\\nRenouveller Flux Forms Pro\\n',
  'Get more from Flux Forms Pro' => '\\nObtenez plus de Flux Forms Pro\\n',
  'Renew your subscription to restore all Pro features and add-ons.' => '\\nRenouvelez votre abonnement pour restaurer toutes les fonctionnalités et modules complémentaires Pro.\\n',
  'Unlock premium add-ons, unlimited features and priority support for your forms.' => '\\nDébloquez des modules complémentaires premium, des fonctionnalités illimitées et une assistance prioritaire pour vos formulaires.\\n',
  'Renew Pro' => '\\nRenouveller Pro\\n',
  'Email delivery is working' => '\\nLa livraison par e-mail fonctionne\\n',
  'The automated Flux Forms email delivery test completed successfully.' => '\\nLe test automatisé de livraison des e-mails Flux Forms s\'est terminé avec succès.\\n',
  'You can attach up to %1$d file here. Please wait about %2$d minutes before trying again.' . chr(0) . 'You can attach up to %1$d files here. Please wait about %2$d minutes before trying again.' => '[[\'Vous pouvez joindre jusqu\'au fichier%1$dici. Veuillez patienter environ%2$dminutes avant de réessayer.\', \'fr\']]' . chr(0) . '[[\'Vous pouvez joindre jusqu\'à%1$ddes fichiers ici. Veuillez patienter environ%2$dminutes avant de réessayer.\', \'fr\']]',
  'This file is too large. The maximum size for this field is %s.' => '\\nCe fichier est trop volumineux. La taille maximale de ce champ est%s.\\n',
  'This file type is not accepted here. Please attach one of the file types listed on the field.' => '\\nCe type de fichier n\'est pas accepté ici. Veuillez joindre l\'un des types de fichiers répertoriés dans ce champ.\\n',
  'This file appears to be empty. Please choose a different file.' => '\\nCe fichier semble être vide. Veuillez choisir un autre fichier.\\n',
  'The uploaded file could not be verified. Please attach it again.' => '\\nLe fichier téléchargé n\'a pas pu être vérifié. Veuillez le joindre à nouveau.\\n',
  'X-WP-Nonce header is missing' => '\\nL\'en-tête X-WP-Nonce est manquant\\n',
  'Your form session has expired. Please reload the page.' => '\\nVotre session de formulaire a expiré. Veuillez recharger la page.\\n',
  'Form ID:' => '\\nID du formulaire :\\n',
  'The form will be displayed on the frontend.' => '\\nLe formulaire sera affiché sur le frontend.\\n',
  'This link uses an older format. For improved security, new email notifications include updated links.' => '\\nCe lien utilise un format plus ancien. Pour une sécurité améliorée, les nouvelles notifications par e-mail incluent des liens mis à jour.\\n',
  'It seems that you are the admin of this form. Please log in and try again.' => '\\nIl semble que vous soyez l\'administrateur de ce formulaire. Veuillez vous connecter et réessayer.\\n',
  'Flux Forms couldn\'t locate the form settings. Please check your settings or contact support for assistance.' => '\\nFlux Forms n\'a pas pu localiser les paramètres du formulaire. Veuillez vérifier vos paramètres ou contacter l\'assistance pour obtenir de l\'aide.\\n',
  'Y/m/d \\a\\t g:ia' => '\\nY/m/d \\\\a\\\\t g:ia\\n',
  'Too many attempts. Please wait a few minutes and try again.' => '\\nTrop de tentatives. Veuillez patienter quelques minutes et réessayer.\\n',
  'The recording upload could not be verified. Please record it again and retry.' => '[[\'Le téléchargement de l\'enregistrement n\'a pas pu être vérifié. Veuillez l\'enregistrer à nouveau et réessayer.\\n',
  'This recording format is not supported. Please record it again.' => '\\nCe format d\'enregistrement n\'est pas pris en charge. Veuillez l\'enregistrer à nouveau.\\n',
  'The server could not verify the recording format. Please contact the site administrator.' => '\\nLe serveur n\'a pas pu vérifier le format d\'enregistrement. Veuillez contacter l\'administrateur du site.\\n',
  'The recording format could not be verified. Please record it again.' => '\\nLe format d\'enregistrement n\'a pas pu être vérifié. Veuillez l\'enregistrer à nouveau.\\n',
  'The server could not verify the recording duration. Please record it again and try uploading.' => '\\nLe serveur n\'a pas pu vérifier la durée de l\'enregistrement. Veuillez l\'enregistrer à nouveau et essayer de le télécharger.\\n',
  'The server could not store the recording. Please try again or contact the site administrator.' => '\\nLe serveur n\'a pas pu stocker l\'enregistrement. Veuillez réessayer ou contacter l\'administrateur du site.\\n',
  'The recording request could not be verified. Please retry.' => '\\nLa demande d\'enregistrement n\'a pas pu être vérifiée. Veuillez réessayer.\', \'fr\']]',
  'The upload request could not be verified. Please try again.' => '\\nLa demande de téléchargement n\'a pas pu être vérifiée. Veuillez réessayer.\\n',
  'The upload field could not be verified. Please refresh the form and try again.' => '\\nLe champ de téléchargement n\'a pas pu être vérifié. Veuillez actualiser le formulaire et réessayer.\\n',
  'The response box could not be verified. Reopen the conversation and try again.' => '\\nLa boîte de réponse n\'a pas pu être vérifiée. Rouvrez la conversation et réessayez.\\n',
  'The response attachment could not be secured. Please try again.' => '\\nLa pièce jointe de réponse n\'a pas pu être sécurisée. Veuillez réessayer.\\n',
  'Not allowed to respond to this message.' => '\\nPas autorisé à répondre à ce message.\\n',
  'Payment Intent ID is missing' => '[[\'L\'ID d\'intention de paiement est manquant\\n',
  'persiaPayment' => '\\npersiaPaiement\\n',
  'The Email Address Is Not Valid' => '\\nL\'adresse e-mail n\'est pas valide\\n',
  'The Username Must Contain Only Letters, Numbers And Lowercase letters' => '\\nLe nom d\'utilisateur doit contenir uniquement des lettres, des chiffres et des lettres minuscules\', \'en\']]',
  'The Username Must Contain At Least 3 Characters.' => '\\nLe nom d\'utilisateur doit contenir au moins 3 caractères.\\n',
  'The Password Must Contain At Least 8 Characters!' => '\\nLe mot de passe doit contenir au moins 8 caractères !\\n',
  'The Password Must Contain At Least 1 Number!' => '\\nLe mot de passe doit contenir au moins 1 chiffre !\\n',
  'The Password Must Contain At Least 1 Capital Letter!' => '\\nLe mot de passe doit contenir au moins 1 lettre majuscule !\\n',
  'The Password Must Contain At Least 1 Lowercase Letter!' => '\\nLe mot de passe doit contenir au moins 1 lettre minuscule !\\n',
  'Audio recording' => '\\nEnregistrement audio\\n',
  'Video recording' => '\\nEnregistrement vidéo\\n',
  'Screen recording' => '\\nEnregistrement d\'écran\\n',
  'Form Preview' => '\\nAperçu du formulaire\\n',
  'Create New Password' => '\\nCréer un nouveau mot de passe\\n',
  'Create a secure password for your account' => '\\nCréez un mot de passe sécurisé pour votre compte\\n',
  'New Password' => '\\nNouveau mot de passe\\n',
  'Enter your new password' => '\\nEntrez votre nouveau mot de passe\\n',
  'Set Password' => '\\nDéfinir le mot de passe\\n',
  'Error! Please try again later.' => '\\nErreur ! Veuillez réessayer plus tard.\\n',
  'Password has been changed successfully!' => '\\nLe mot de passe a été modifié avec succès !\\n',
  'Invalid payment selection. Please review your choices and try again. If the problem persists, contact the site administrator.' => '\\nSélection de paiement non valide. Veuillez revoir vos choix et réessayer. Si le problème persiste, contactez l\'administrateur du site.\\n',
  'If your emails are not being delivered, try using an SMTP plugin. For more information, %1$s click here %2$s or contact our %3$s support team %4$s.' => '\\nSi vos e-mails ne sont pas livrés, essayez d\'utiliser un plugin SMTP. Pour plus d\'informations,%1$scliquez ici%2$sou contactez notre équipe d\'assistance%3$s%4$s.\\n',
  'View Messages' => '\\nAfficher les messages\\n',
  'Hello!' => '\\nBonjour !\\n',
  'New Message' => '\\nNouveau message\\n',
  'New message received' => '\\nNouveau message reçu\\n',
  'We received your message' => '\\nNous avons reçu votre message\\n',
  'This email was sent automatically. Please do not reply.' => '\\nCet e-mail a été envoyé automatiquement. Veuillez ne pas répondre.\\n',
  'Built with %1$sYT Form%2$s by %3$sWhiteStudio.team%4$s' => '\\nConstruit avec%1$sYT Form%2$spar%3$sWhiteStudio.team%4$s\\n',
  'Weekly Flux Forms report' => '\\nRapport hebdomadaire sur les formulaires de flux\\n',
  'Pro features are paused' => '\\nLes fonctionnalités Pro sont suspendues\\n',
  'Congratulations! Email System Working' => '\\nFélicitations ! Le système de messagerie fonctionne\\n',
  'Your server has successfully sent this test email. The email delivery system is properly configured and functioning.' => '\\nVotre serveur a envoyé avec succès cet e-mail de test. Le système de distribution de courrier électronique est correctement configuré et fonctionne.\\n',
  'Email Delivery Tips' => '\\nConseils pour l\'envoi d\'e-mails\\n',
  'Form submitted successfully without tracking.' => '\\nFormulaire soumis avec succès sans suivi.\\n',
  'Your message has been received and recorded successfully.' => '\\nVotre message a été reçu et enregistré avec succès.\\n',
  'Reset Password' => '\\nRéinitialiser le mot de passe\\n',
  'Or copy and paste this link:' => '\\nOu copiez et collez ce lien :\\n',
  'If you did not request this, you can safely ignore it.' => '\\nSi vous ne l\'avez pas demandé, vous pouvez l\'ignorer en toute sécurité.\\n',
  'Hi' => '\\nBonjour\\n',
  'You have requested to reset your password.' => '\\nVous avez demandé la réinitialisation de votre mot de passe.\\n',
  'Click the button below to set a new password. This link will be valid for 24 hours.' => '\\nCliquez sur le bouton ci-dessous pour définir un nouveau mot de passe. Ce lien sera valide pendant 24 heures.\\n',
  'Verify Email' => '\\nVérifier l\'e-mail\\n',
  'Your account has been successfully created!' => '\\nVotre compte a été créé avec succès !\\n',
  'Please verify your email address by clicking the button below. This activation link will be valid for 24 hours.' => '\\nVeuillez vérifier votre adresse e-mail en cliquant sur le bouton ci-dessous. Ce lien d\'activation sera valide pendant 24 heures.\\n',
  'A new user has registered on your website.' => '\\nUn nouvel utilisateur s\'est enregistré sur votre site Web.\\n',
  'The user has been sent a verification email to confirm their account.' => '\\nL\'utilisateur a reçu un e-mail de vérification pour confirmer son compte.\\n',
  'This is an alert message regarding a SID validation error. This issue may have occurred due to a plugin conflict or an unauthorized attempt to access the website.' => '\\nIl s\'agit d\'un message d\'alerte concernant une erreur de validation SID. Ce problème peut être dû à un conflit de plug-in ou à une tentative non autorisée d\'accès au site Web.\\n',
  'If you receive this email multiple times, it could indicate a recurring issue.' => '\\nSi vous recevez cet e-mail plusieurs fois, cela peut indiquer un problème récurrent.\\n',
  'Please contact our support team for assistance.' => '\\nVeuillez contacter notre équipe d\'assistance pour obtenir de l\'aide.\\n',
  'One or more of the plugins listed below—typically related to caching or security—might be triggering this issue. For troubleshooting, temporarily deactivate them and test your site.' => '\\nUn ou plusieurs plug-ins répertoriés ci-dessous, généralement liés à la mise en cache ou à la sécurité, peuvent être à l\'origine de ce problème. Pour le dépannage, désactivez-les temporairement et testez votre site.\\n',
  'SID Validation Error' => '\\nErreur de validation SID\\n',
  'Please select a form to display.' => '\\nVeuillez sélectionner un formulaire à afficher.\\n',
  'Sürükle-bırak form oluşturucu: çok adımlı formlar, Stripe ödemeleri, koşullu mantık, dashboard, otomasyonlar ve Flux Certificates entegrasyonu. Easy Form Builder (WhiteStudio, GPL) tabanlı fork.' => '[[\'Générateur de formulaires par glisser-déposer : formulaires en plusieurs étapes, paiements Stripe, logique conditionnelle, tableau de bord, automatisations et intégration de certificats Flux. Fork basé sur Easy Form Builder (WhiteStudio, GPL).\', \'tr\']]',
  'The currency of this form is not supported.' => '[[\'La devise de ce formulaire n\'est pas prise en charge.\\n',
  'The Stripe secret key is not configured.' => '\\nLa clé secrète Stripe n\'est pas configurée.\\n',
  'Could not connect to Stripe: %s' => '\\nImpossible de se connecter à Stripe :%s\', \'en\']]',
  'Stripe API error (HTTP %d).' => '\\nErreur API Stripe (HTTP%d).\', \'fr\']]',
 ),
);
